parameters.jsCode:
// Reincorpora SOLO los campos observados de cada corrección, sin cruzar temas ni recursos.
// Mode: Run Once for All Items.
// Los campos a reemplazar salen de la marca "[campo: …]" que «Auditar borrador» pone en cada error. Una corrección que
// falte, venga incompleta o empeore el texto no detiene el flujo: se conserva lo anterior y la próxima auditoría lo
// vuelve a señalar (o queda como pendiente).
const tareas = $('Preparar ajustes individuales').all(0, $runIndex).map(x => x.json);
const audit = $('Auditar borrador').all(0, $runIndex)[0].json;
const borradores = JSON.parse(JSON.stringify(audit.borradores || []));

function desempaquetar(dato, profundidad = 0) {
  if (profundidad > 9) return [dato];
  if (typeof dato === 'string') {
    try { return desempaquetar(JSON.parse(dato), profundidad + 1); } catch { return [dato]; }
  }
  if (Array.isArray(dato)) return dato.flatMap(x => desempaquetar(x, profundidad + 1));
  if (!dato || typeof dato !== 'object') return [dato];
  for (const k of ['output', 'correcciones', 'resultados', 'items']) {
    if (Array.isArray(dato[k])) return desempaquetar(dato[k], profundidad + 1);
  }
  if (dato.output && !dato.resultado) return desempaquetar(dato.output, profundidad + 1);
  if (typeof dato.text === 'string' && !dato.resultado) return desempaquetar(dato.text, profundidad + 1);
  return [dato];
}

const propuestas = $input.all().flatMap(it => desempaquetar(it.json ?? it)).filter(p => p && typeof p === 'object');
const key = obj => `${Number(obj.tema_numero)}|${String(obj.tipo)}|${Number(obj.posicion)}`;
const porClave = new Map(propuestas.map(p => [key(p), p]));
const contar = arr => Array.isArray(arr) ? arr.reduce((n, s) => n + (String(s?.texto ?? '').trim().match(/\S+/g) || []).length, 0) : 0;
const distancia = (n, t) => {
  const d = t.diagnostico_longitud;
  if (!d) return 0;
  return n < d.minimo_obligatorio ? d.minimo_obligatorio - n : n > d.maximo_obligatorio ? n - d.maximo_obligatorio : 0;
};
const modelo = x => x.output || x;
const camposDe = errores => new Set((errores || []).flatMap(e => {
  const m = /\[campo:\s*([^\]]+)\]\s*$/.exec(e);
  return m ? m[1].split(',').map(s => s.trim()).filter(Boolean) : [];
}));
const omitidos = []; // [índice del tema, motivo]

tareas.forEach((t, k) => {
  // Si el modelo cambió tema o posición, se usa la respuesta que ocupa el mismo lugar que la tarea.
  const corregido = porClave.get(key(t)) || (propuestas.length === tareas.length ? propuestas[k] : null);
  const nuevo = corregido && corregido.resultado;
  const destino = borradores[t.tema_indice] && modelo(borradores[t.tema_indice]);
  if (!nuevo || typeof nuevo !== 'object' || Array.isArray(nuevo) || !destino) {
    omitidos.push([t.tema_indice, `tema ${t.tema_numero} ${t.tipo} ${t.posicion}: sin respuesta del editor`]);
    return;
  }
  const campos = camposDe(t.errores);
  if (!campos.size) campos.add('contenido');

  let objetivo;
  if (t.tipo === 'recurso') {
    objetivo = (destino.recursos || []).find(r => Number(r.posicion) === Number(t.posicion));
    if (!objetivo) {
      // El modelo omitio este recurso: se agrega con lo que redacto el corrector.
      objetivo = { posicion: Number(t.posicion) };
      destino.recursos = [...(destino.recursos || []), objetivo].sort((a, b) => Number(a.posicion) - Number(b.posicion));
    }
  } else if (t.tipo === 'presentacion') {
    objetivo = destino.presentacion = destino.presentacion || {};
  } else if (t.tipo === 'evaluacion') {
    objetivo = destino.evaluacion = destino.evaluacion || {};
  } else {
    omitidos.push([t.tema_indice, `tipo de corrección desconocido: ${t.tipo}`]);
    return;
  }

  for (const campo of campos) {
    if (!Object.prototype.hasOwnProperty.call(nuevo, campo)) {
      omitidos.push([t.tema_indice, `tema ${t.tema_numero} ${t.tipo} ${t.posicion}: el editor no devolvió ${campo}`]);
      continue;
    }
    if (campo === 'contenido' && t.tipo === 'recurso') {
      const c = Array.isArray(nuevo.contenido)
        ? nuevo.contenido.map(s => (s && !s.texto && s.texto_visible ? { ...s, texto: s.texto_visible } : s))
        : null;
      if (!c || c.length < 2 || c.some(s => !s?.rotulo || !s?.texto || !s?.visual || typeof s?.texto_visible !== 'string')) {
        omitidos.push([t.tema_indice, `tema ${t.tema_numero} recurso ${t.posicion}: contenido corregido incompleto`]);
        continue;
      }
      // La extensión total la ajusta el subflujo de longitud; aquí solo se evita que una corrección recorte el guion
      // a menos de la mitad cuando ya estaba dentro de la hoja.
      if (distancia(contar(objetivo.contenido), t) === 0 && distancia(contar(c), t) > 0 && contar(c) < contar(objetivo.contenido) * 0.5) {
        omitidos.push([t.tema_indice, `tema ${t.tema_numero} recurso ${t.posicion}: la corrección recortaba el guion a menos de la mitad`]);
        continue;
      }
      objetivo.contenido = c;
      continue;
    }
    objetivo[campo] = nuevo[campo];
  }
});

return borradores.map((b, i) => ({ json: {
  ...b,
  correcciones_omitidas: [...(b.correcciones_omitidas || []), ...omitidos.filter(([ti]) => ti === i).map(([, m]) => m)]
} }));

// Sale del ciclo de corrección con los borradores de la última auditoría (ya con sus reparaciones automáticas).
// Lo que la auditoría todavía no aprueba se adjunta a cada tema como «pendientes_qa»: se informa en el documento y en
// la respuesta, pero ya no detiene la creación de los guiones.
const r = $input.first().json;
if (!Array.isArray(r.borradores)) throw new Error('Faltan borradores tras QA');
const temas = $('Completar requisitos RED').all().map(x => x.json);
const sinCampo = e => String(e).replace(/\s*\[campo:[^\]]*\]\s*$/, '');
return r.borradores.map((b, i) => {
  const n = temas[i] && temas[i].tema ? temas[i].tema.numero : i + 1;
  const propios = e => String(e).startsWith('Tema ' + n + ': ');
  return {
    json: {
      ...b,
      pendientes_qa: [...(r.errores || []).filter(propios), ...(r.avisos || []).filter(propios)].map(sinCampo)
    }
  };
});

