parameters.jsCode:
// Nodo Code: «Elegir hoja de estructura RED» · Modo: Run Once for All Items
// Toma el nivel de formación que detectó «Extraer unidad» (primero el del Syllabus, si no el del
// documento de la unidad) y arma la consulta a la hoja "Estructura RED - <nivel>" de Drive (todas sus pestañas).
// Hojas: carpeta https://drive.google.com/drive/folders/1MoyIJAJNFCCCGiM2hMlfqmMkCMbt8tSz

const HOJAS = {
  'Profesional': '1A_UkvHZxJaC5J0TEyu_HqHtOlVWqtSoZk2hT4fCgINU',
  'Tecnólogo': '1JRdVqJ1c4WYFFhVjC17cyA3S_HehJFEYPmI1HbsHC4I',
  'Especialización': '1ts_IZ444YVV74OTt4nydAWsF4vVf62ZY7_gzHl4o0bs',
  'Doctorado': '1fTnN3QqrZlM-eb09nOg052CEYAHot3GNYo-y7qCFznI'
};

const temas = $('Extraer unidad').all();
const nivel = temas[0] && temas[0].json.nivel_formacion;
const clave = nivel && (nivel.clave === 'Licenciatura' ? 'Profesional' : nivel.clave);
const id = clave ? HOJAS[clave] : null;

// Sin nivel reconocido la consulta falla a propósito (404) y el flujo sigue con las reglas generales.
const hoja = id || 'sin-nivel-reconocido';
return [{
  json: {
    nivel: clave || null,
    fuente_nivel: nivel ? nivel.fuente : null,
    hoja_id: id,
    // Se leen TODAS las pestañas: los nombres cambian entre hojas (OVIs/OVAs en unas, «RED» en otras).
    // «Normalizar hoja RED» reconoce cada pestaña por sus encabezados.
    url: 'https://sheets.googleapis.com/v4/spreadsheets/' + hoja + '?includeGridData=true&fields=' +
      encodeURIComponent('sheets(properties(title),data(rowData(values(formattedValue))))')
  }
}];

// Nodo Code: «Armar estructura RED» · Modo: Run Once for All Items
