const temas = $('Extraer unidad').all();
const eleccion = $('Elegir hoja de estructura RED').first().json;
const respuesta = (($input.first() || {}).json) || {};
const NIVEL = eleccion.nivel === 'Licenciatura' ? 'Profesional' : eleccion.nivel;
const copia = (typeof RESPALDO !== 'undefined' && NIVEL && RESPALDO[NIVEL]) || null;

const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const texto = x => String(x ?? '').replace(/\r/g, '').trim();
const plano = x => texto(x).replace(/\s*\n\s*/g, ' ').replace(/\s+/g, ' ');
const aNum = s => { const t = String(s).trim(); return /^\d{1,3}(\.\d{3})+$/.test(t) ? Number(t.replace(/\./g, '')) : Number(t.replace(',', '.')); };
const RANGO = '(\\d[\\d.]*)\\s*(?:a|–|-|—)\\s*(\\d[\\d.]*)';
const par = m => (m ? [aNum(m[1]), aNum(m[2])].sort((a, b) => a - b) : null);
const buscar = (t, sufijo) => par(new RegExp(RANGO + '\\s*' + sufijo, 'i').exec(t));

// ---------- límites numéricos a partir del texto de la columna Extensión ----------
function limitesDe(extension) {
  const t = plano(extension);
  const unidades = '(?:bloques|[ií]tems|items|hitos|eventos|acontecimientos|nodos|pesta[ñn]as|paneles|diapositivas|elementos|secciones|puntos|hotspots|pasos|pares|preguntas|t[eé]rminos|pantallas|alternativas|decisiones|variables|criterios)';
  const L = { palabras_total: null, palabras_total_visible: null, elementos: null, palabras_por_elemento: null, duracion_min: null, preguntas: null };
  L.palabras_total = par(new RegExp('(?:gui[oó]n[^:]*|extensi[oó]n)\\s*:\\s*' + RANGO + '\\s*palabras', 'i').exec(t)) ||
    par(new RegExp('gui[oó]n\\s+de\\s+' + RANGO + '\\s*palabras', 'i').exec(t));
  L.palabras_total_visible = par(new RegExp(RANGO + '\\s*palabras en total', 'i').exec(t)) ||
    par(new RegExp('total recomendado\\s*:\\s*' + RANGO + '\\s*palabras', 'i').exec(t));
  // «6 a 8 nodos» o, en las hojas que lo escriben al revés, «Nodos: 10-16»
  L.elementos = buscar(t, unidades) || par(new RegExp(unidades + '(?: en total| principales)?\\s*:\\s*' + RANGO, 'i').exec(t));
  L.preguntas = buscar(t, 'preguntas');
  L.caso = par(new RegExp('caso[^:]*:\\s*' + RANGO + '\\s*palabras', 'i').exec(t)) || par(new RegExp('caso de ' + RANGO + '\\s*palabras', 'i').exec(t));
  L.duracion_min = buscar(t, 'minutos');
  const porElemento = par(new RegExp(RANGO + '\\s*palabras\\s*(?:por|/)', 'i').exec(t)) ||
    par(new RegExp('(?:contenido|desarrollo|explicaci[oó]n|ficha|texto|descripci[oó]n|informaci[oó]n ampliada)[^:]*:\\s*' + RANGO + '\\s*palabras', 'i').exec(t));
  if (porElemento) L.palabras_por_elemento = porElemento;
  else {
    const car = par(new RegExp('(?:contenido|descripci[oó]n|texto)[^:]*:\\s*' + RANGO + '\\s*caracteres', 'i').exec(t)) ||
      par(new RegExp(RANGO + '\\s*caracteres\\s*por', 'i').exec(t));
    if (car) L.palabras_por_elemento = [Math.round(car[0] / 6), Math.round(car[1] / 6)];
  }
  return L;
}

// ---------- claves para emparejar nombres (el insumo y la hoja nombran distinto) ----------
function claveRecurso(nombre) {
  const n = norm(nombre);
  if (!n) return null;
  if (/diapositivas|asignatura/.test(n)) return 'presentacion_asignatura'; // la fila de la hoja dice "…/ *Infografía": va antes que infografías
  if (/infograf/.test(n)) return /interactiv/.test(n) ? 'infografia_interactiva' : 'infografia_estatica';
  if (/linea.*tiempo/.test(n)) return 'linea_tiempo';
  if (/diagrama.*flujo/.test(n)) return 'diagrama_flujo';
  if (/mapa.*conceptual/.test(n)) return 'mapa_conceptual';
  if (/micro ?lecci/.test(n)) return 'micro_leccion';
  if (/micro/.test(n)) return 'video_micro';
  if (/video/.test(n)) return /explicativ/.test(n) ? 'video_explicativo' : 'video_academico';
  if (/podcast/.test(n)) return 'podcast';
  if (/presentacion|multimedia/.test(n)) return 'presentacion_multimedia';
  if (/acordeon/.test(n)) return 'acordeon';
  if (/galeria/.test(n)) return 'galeria';
  if (/lectura/.test(n)) return 'lectura';
  if (/laboratorio/.test(n)) return 'laboratorio';
  // Recurso sin regla propia (fichas, simuladores, matrices, casos…): clave derivada del nombre, en singular y sin conectores,
  // para emparejar el insumo con su fila de la hoja aunque cambie el plural o el artículo.
  const conectores = ['de', 'del', 'la', 'las', 'los', 'el', 'y', 'e', 'en', 'con', 'para', 'por', 'a', 'al', 'un', 'una'];
  const palabras = n.split(' ').filter(w => w && !conectores.includes(w)).map(w => (w.length > 3 ? w.replace(/(es|s)$/, '') : w));
  const clave = palabras.join('_');
  return clave.length >= 3 ? clave : null;
}
function claveActividad(nombre) {
  const n = norm(nombre);
  if (!n) return null;
  if (/emparej/.test(n)) return 'emparejamiento';
  if (/decision/.test(n)) return 'toma_decisiones';
  if (/arrastr/.test(n)) return 'arrastre';
  if (/crucigrama/.test(n)) return 'crucigrama';
  if (/simulaci/.test(n)) return 'simulacion';
  if (/clasific/.test(n)) return 'clasificacion';
  if (/cuestionario/.test(n)) return 'cuestionario';
  if (/estudio.*caso|caso.*guiado/.test(n)) return 'estudio_caso';
  if (/tarea/.test(n)) return 'tarea';
  if (/taller/.test(n)) return 'taller';
  if (/laboratorio/.test(n)) return 'laboratorio';
  if (/rubrica/.test(n)) return 'rubrica';
  if (/gamific/.test(n)) return 'gamificacion';
  if (/foro/.test(n)) return 'foro';
  return null;
}

// ---------- lectura de las hojas ----------
const rangosVivos = Array.isArray(respuesta.valueRanges) ? respuesta.valueRanges : [];
const rangosCopia = copia ? Object.entries(copia).map(([k, v]) => ({ range: k + '!A1', values: v })) : [];
const valoresDe = rangos => nombre => {
  const r = rangos.find(x => norm(String(x.range || '').split('!')[0]) === norm(nombre));
  return (r && r.values) || [];
};
const filasTras = (filas, esCabecera) => {
  const i = filas.findIndex(f => esCabecera(f.map(norm)));
  if (i < 0) return { cab: [], datos: [] };
  return { cab: filas[i].map(norm), datos: filas.slice(i + 1).filter(f => f.some(c => texto(c))) };
};
const col = (cab, re) => cab.findIndex(c => re.test(c));

function leerRecursos(filas, tabla) {
  const { cab, datos } = filasTras(filas, c => c.includes('recurso') && c.some(x => x.startsWith('estructura')));
  const iNom = col(cab, /^recurso$/), iEst = col(cab, /^estructura/), iExt = col(cab, /^extension/);
  const iCat = col(cab, /^categoria/), iImg = col(cab, /^imagen de referencia/);
  const salida = {};
  for (const f of datos) {
    const nombre = texto(f[iNom]);
    const k = claveRecurso(nombre);
    if (!k || salida[k]) continue;
    salida[k] = {
      nombre_en_hoja: nombre, tabla, categoria: texto(f[iCat]),
      estructura: texto(f[iEst]), extension: texto(f[iExt]),
      indicacion_visual: iImg >= 0 && !/^referencia sugerida/i.test(texto(f[iImg])) ? texto(f[iImg]) : '',
      limites: limitesDe(f[iExt])
    };
  }
  return salida;
}
function leerActividades(filas) {
  const { cab, datos } = filasTras(filas, c => c.some(x => x.startsWith('estructura')) && (c.includes('actividad') || c.includes('h') || c.some(x => x.startsWith('uso recomendado'))));
  let iNom = col(cab, /^actividad$/); if (iNom < 0) iNom = col(cab, /^h$/);
  const iEst = col(cab, /^estructura/), iExt = col(cab, /^extension/), iUso = col(cab, /^uso recomendado/), iCat = col(cab, /^categoria/);
  const salida = {};
  for (const f of datos) {
    const nombre = texto(f[iNom]);
    const k = claveActividad(nombre);
    if (!k || salida[k]) continue;
    const uso = iUso >= 0 ? texto(f[iUso]) : '';
    salida[k] = {
      nombre_en_hoja: nombre, categoria: texto(f[iCat]), uso_recomendado: /^[A-Za-zÁ-ú ]+$/.test(uso) ? uso : '',
      estructura: texto(f[iEst]), extension: iExt >= 0 ? texto(f[iExt]) : '',
      limites: limitesDe(iExt >= 0 ? f[iExt] : f[iEst])
    };
  }
  return salida;
}
function leerEvaluaciones(filas) {
  const { cab, datos } = filasTras(filas, c => c.some(x => x.startsWith('estructura')) && c.some(x => x.includes('evaluacion')));
  let iNom = col(cab, /^nombre/); if (iNom < 0) iNom = col(cab, /^evaluacion$/);
  const iEst = col(cab, /^estructura/), iExt = col(cab, /^extension/);
  const salida = {};
  for (const f of datos) {
    const k = /formativa/.test(norm(f[iNom])) ? 'formativa' : /sumativa/.test(norm(f[iNom])) ? 'sumativa' : null;
    if (!k || salida[k]) continue;
    const ext = iExt >= 0 ? texto(f[iExt]) : '';
    salida[k] = { nombre_en_hoja: texto(f[iNom]), estructura: texto(f[iEst]), extension: ext, preguntas: limitesDe(texto(f[iEst]) + ' ' + ext).preguntas };
  }
  return salida;
}
function leerPerfil(filas) {
  const i = filas.findIndex(f => norm(f[0]) === 'nivel' && f.length > 2);
  if (i < 0 || !filas[i + 1]) return null;
  const perfil = {};
  filas[i].forEach((c, k) => { if (k && texto(c) && texto(filas[i + 1][k])) perfil[norm(c).replace(/ /g, '_')] = texto(filas[i + 1][k]); });
  return Object.keys(perfil).length ? perfil : null;
}

const leerTodo = rangos => {
  if (!rangos.length) return null;
  const v = valoresDe(rangos);
  return {
    recursos: { ...leerRecursos(v('OVAs'), 'OVA'), ...leerRecursos(v('OVIs'), 'OVI') },
    actividades: leerActividades(v('Actividades')),
    evaluaciones: leerEvaluaciones(v('Evaluaciones')),
    perfil: leerPerfil(v('OVIs'))
  };
};
const vivo = leerTodo(rangosVivos);
const resp = leerTodo(rangosCopia);
const cargado = !!(vivo || resp);
// La hoja en vivo manda; la copia solo rellena lo que la hoja no trae.
const catRecursos = { ...(resp ? resp.recursos : {}), ...(vivo ? vivo.recursos : {}) };
const catActividades = { ...(resp ? resp.actividades : {}), ...(vivo ? vivo.actividades : {}) };
const evaluaciones = { ...(resp ? resp.evaluaciones : {}), ...(vivo ? vivo.evaluaciones : {}) };
const perfil = (vivo && vivo.perfil) || (resp && resp.perfil) || null;
const fuenteDatos = vivo ? 'hoja de Drive en vivo' : 'copia incluida en el flujo';

const motivo = respuesta.error
  ? String((respuesta.error.message || respuesta.error)).slice(0, 200)
  : (!eleccion.nivel ? 'no se reconoció el nivel de formación' : 'la respuesta no trajo datos');

return temas.map((item, idx) => {
  const j = item.json;
  const avisos = [];
  if (!vivo && cargado) {
    avisos.push('No se pudo leer la hoja "Estructura RED - ' + NIVEL + '" (' + motivo +
      '): se usa la copia de esa estructura incluida en el flujo (revisa que la cuenta de Drive tenga acceso a Google Sheets).');
  }
  if (!cargado) {
    avisos.push('No se pudo leer la hoja "Estructura RED' + (eleccion.nivel ? ' - ' + eleccion.nivel : '') + '" (' + motivo +
      '): se usan las reglas generales de estructura y extensión.');
    return { json: { ...j, advertencias_insumo: [...(j.advertencias_insumo || []), ...avisos] }, pairedItem: { item: idx } };
  }
  const recursos = (j.recursos || []).map(r => {
    const out = { ...r };
    const spec = catRecursos[claveRecurso(r.formato)];
    if (spec) out.estructura_red = spec;
    else avisos.push('El formato "' + r.formato + '" no está en la hoja Estructura RED de ' + NIVEL + ': se usan las reglas generales.');
    if (r.tipo === 'OVA') {
      const act = catActividades[claveActividad(r.actividad_enunciado)];
      if (act) out.actividad_estructura = act;
      else avisos.push('La actividad "' + r.actividad_enunciado + '" no está en la hoja Estructura RED de ' + NIVEL + ': se usan las reglas generales.');
    }
    return out;
  });
  return {
    json: {
      ...j,
      recursos,
      estructura_red: { nivel: NIVEL, fuente_nivel: eleccion.fuente_nivel, hoja: 'Estructura RED - ' + NIVEL, fuente_datos: fuenteDatos, perfil_nivel: perfil, evaluaciones },
      advertencias_insumo: [...(j.advertencias_insumo || []), ...[...new Set(avisos)]]
    },
