// Nivel del flujo → plantilla.
const NIVELES = {
  'Doctorado': 'Doctorado',
  'Especialización': 'Especializacion',
  'Profesional': 'Profesional',
  'Licenciatura': 'Profesional',
  'Tecnólogo': 'Tecnologico',
  'Tecnológico': 'Tecnologico'
};
const NIVEL_POR_DEFECTO = 'Profesional';

// Formato del recurso → bloque de la plantilla.
const BLOQUES = {
  presentacion_asignatura: '00', infografia_estatica: '01', infografia_interactiva: '02', diagrama_flujo: '03',
  mapa_conceptual: '04', video_academico: '05', video_explicativo: '06', video_micro: '07', podcast: '08',
  presentacion_multimedia: '09', acordeon: '10', galeria: '11', lectura: '12', linea_tiempo: '13'
};

const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const limpio = x => String(x ?? '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').trim();
function claveRecurso(nombre) {
  const n = norm(nombre);
  if (!n) return null;
  if (/infograf/.test(n)) return /interactiv/.test(n) ? 'infografia_interactiva' : 'infografia_estatica';
  if (/linea.*tiempo/.test(n)) return 'linea_tiempo';
  if (/diagrama.*flujo/.test(n)) return 'diagrama_flujo';
  if (/mapa.*conceptual/.test(n)) return 'mapa_conceptual';
  if (/micro/.test(n)) return 'video_micro';
  if (/video/.test(n)) return /explicativ/.test(n) ? 'video_explicativo' : 'video_academico';
  if (/podcast/.test(n)) return 'podcast';
  if (/diapositivas de presentacion|presentacion de la asignatura/.test(n)) return 'presentacion_asignatura';
  if (/presentacion|multimedia/.test(n)) return 'presentacion_multimedia';
  if (/acordeon/.test(n)) return 'acordeon';
  if (/galeria/.test(n)) return 'galeria';
  if (/lectura/.test(n)) return 'lectura';
  return null;
}

const carpeta = $('Crear carpeta de guiones').first().json;
if (!carpeta.id) throw new Error('Drive no devolvió el ID de la carpeta de guiones.');

const reensamblados = $('Reensamblar recursos ajustados').all().map(x => x.json);
const requisitos = $('Completar requisitos RED').all().map(x => x.json);

const valorDe = (reemplazos, marcador) => {
  const r = (reemplazos || []).find(x => x.marcador === marcador);
  return r ? limpio(r.valor) : '';
};

// Texto plano de un recurso completo, para el anexo.
const textoRecurso = (rec, complementos) => [
  rec.titulo ? 'Título: ' + limpio(rec.titulo) : '',
  ...(rec.contenido || []).map(s => [limpio(s.rotulo), limpio(s.texto_visible), limpio(s.texto), s.visual ? 'Visual: ' + limpio(s.visual) : '']
    .filter(Boolean).join('\n')),
  ...(complementos || []).map(c => limpio(c.rotulo) + ': ' + limpio(c.texto)),
  rec.descripcion ? 'Descripción para producción: ' + limpio(rec.descripcion) : ''
].filter(Boolean).join('\n\n');

const textoEvaluacion = (ev, evIa) => [
  'Tipo: ' + limpio(ev.tipo) + (ev.porcentaje ? ' (' + limpio(ev.porcentaje) + ')' : ''),
  ev.objetivo ? 'Objetivo: ' + limpio(ev.objetivo) : '',
  ev.titulo ? 'Título: ' + limpio(ev.titulo) : '',
  evIa.instrucciones ? 'Instrucciones: ' + limpio(evIa.instrucciones) : '',
  ...(ev.contenido || []).map(s => limpio(s.rotulo) + ': ' + limpio(s.texto)),
  evIa.condiciones_entrega ? 'Condiciones de entrega: ' + limpio(evIa.condiciones_entrega) : '',
  ...((ev.rubrica || []).length ? ['Rúbrica:'] : []),
  ...(ev.rubrica || []).map(r => limpio(r.criterio) + ' — Alto: ' + limpio(r.nivel_alto) + ' | Medio: ' + limpio(r.nivel_medio) + ' | Bajo: ' + limpio(r.nivel_bajo))
].filter(Boolean).join('\n');

const tieneActividad = bloque => bloque.campos.some(c => /_ACT_/.test(c[0]));
// Datos del bloque para el modelo (sin los campos de la ficha, que llena el sistema).
const FICHA = /_(CODIGO|TITULO_RECURSO|SUBTEMA)$/;
const fichaModelo = b => ({
  recurso: b.recurso,
  estructura: b.estructura,
  extension: b.extension,
  observaciones: b.observaciones,
  campos: b.campos.filter(c => !FICHA.test(c[0])).map(([marcador, etiqueta, limite, pauta, opcional]) =>
    ({ marcador, etiqueta, limite, pauta, ...(opcional ? { parte_opcional: opcional } : {}) })),
  tablas: b.tablas.map(([id, min, max, columnas, pauta, opcional]) => ({
    id, min, max, pauta, ...(opcional ? { parte_opcional: opcional } : {}),
    columnas: columnas.map(([marcador, titulo, limite]) => ({ marcador, titulo, limite }))
  })),
  partes_opcionales: b.opcionales.map(([id, regla]) => ({ id, regla })),
  control: b.control
});

return $('Armar guion').all().map((item, i) => {
  const j = item.json;
  const g = j.guion || {};
  const rr = j.reemplazos || [];
  const ia = (reensamblados[i] && (reensamblados[i].output || reensamblados[i])) || {};
  const req = requisitos[i] || {};
  if (!Array.isArray(g.recursos) || !g.recursos.length) throw new Error('Tema ' + j.tema + ': no trae recursos.');

  const advertencias = [];
  const nivelFlujo = (req.nivel_formacion && req.nivel_formacion.clave) || (req.estructura_red && req.estructura_red.nivel) || null;
  let nivel = NIVELES[nivelFlujo];
  if (!nivel || !CATALOGOS[nivel]) {
    advertencias.push('No se reconoció el nivel de formación («' + (nivelFlujo || 'vacío') + '»): se usó la plantilla de ' + NIVEL_POR_DEFECTO + '.');
    nivel = NIVEL_POR_DEFECTO;
  }
  const cat = CATALOGOS[nivel];
  const asig = req.asignatura || {};

  const valores = {
    PROGRAMA: valorDe(rr, '<<Programa>>') || limpio(asig.programa),
    NIVEL: valorDe(rr, '<<Pregrado>>') || limpio(asig.nivel_formacion),
    ASIGNATURA: valorDe(rr, '<<Asignatura>>') || j.asignatura,
    PERIODO: limpio(asig.semestre_periodo) || valorDe(rr, '<<Semestre>>'),
    CREDITOS: valorDe(rr, '<<Creditos>>') || limpio(asig.creditos),
    MODALIDAD: limpio(asig.modalidad),
    UNIDAD: j.unidad + '. ' + limpio(j.nombre_unidad),
    TEMA: limpio(j.nombre_tema).replace(/^\s*\d+\.\s*/, j.tema + '. '),
    RESULTADO_APRENDIZAJE: valorDe(rr, '<<Resultado_Aprendizaje>>'),
    INDICADOR: valorDe(rr, '<<Indicadores>>'),
    // Para la respuesta del webhook (no están en la plantilla).
    SEMESTRE: valorDe(rr, '<<Semestre>>'),
    HORAS: valorDe(rr, '<<Duracion>>')
  };
  if (!/^\d/.test(valores.TEMA)) valores.TEMA = j.tema + '. ' + valores.TEMA;

  const bloques = {};   // id de bloque → { origen, posicion }
  const anexo = [];     // { titulo, texto }
  const tareas = [];

  const pres = g.presentacion;
  if (pres && cat.bloques['00']) {
    bloques['00'] = { origen: 'presentacion', posicion: 0 };
    valores.R00_CODIGO = 'U' + j.unidad + '-PRES';
    tareas.push({
      bloque: '00', origen: 'presentacion', posicion: 0,
      plantilla: fichaModelo(cat.bloques['00']),
      contenido_generado: { titulo: pres.titulo, pantallas: pres.contenido || [], descripcion_visual: pres.descripcion_visual || '' }
    });
  }

  g.recursos.forEach((rec, k) => {
    const posicion = k + 1;
    const recIa = (ia.recursos || []).find(x => Number(x.posicion) === posicion) || {};
    const complementos = (Array.isArray(recIa.complementos) ? recIa.complementos : []).filter(c => c && limpio(c.texto));
    const id = BLOQUES[claveRecurso(rec.formato)];
    const etiqueta = 'Recurso ' + posicion + ' · ' + (rec.formato || 'sin formato');
    if (!id || !cat.bloques[id]) {
      advertencias.push(etiqueta + ': la plantilla de ' + nivel + ' no tiene bloque para este formato; su guion va en el anexo del documento.');
      anexo.push({ titulo: etiqueta + ' — ' + limpio(rec.titulo), texto: textoRecurso(rec, complementos) + (rec.actividad ? '\n\nActividad de autoaprendizaje:\n' + limpio(rec.actividad) : '') });
      return;
    }
    if (bloques[id]) {
      advertencias.push(etiqueta + ': la plantilla tiene un solo bloque de este tipo y ya lo usa el recurso ' + bloques[id].posicion + '; su guion va en el anexo del documento.');
      anexo.push({ titulo: etiqueta + ' — ' + limpio(rec.titulo), texto: textoRecurso(rec, complementos) + (rec.actividad ? '\n\nActividad de autoaprendizaje:\n' + limpio(rec.actividad) : '') });
      return;
    }
    const b = cat.bloques[id];
    bloques[id] = { origen: 'recurso', posicion };
    const R = 'R' + id + '_';
    valores[R + 'CODIGO'] = 'U' + j.unidad + '-T' + j.tema + '-R' + posicion;
    valores[R + 'TITULO_RECURSO'] = limpio(rec.titulo);
    valores[R + 'SUBTEMA'] = (rec.subtemas_que_cubre || []).join('\n');
    const conActividad = !!limpio(rec.actividad) && tieneActividad(b);
    if (limpio(rec.actividad) && !conActividad) {
      anexo.push({ titulo: 'Actividad de autoaprendizaje — ' + etiqueta, texto: limpio(rec.actividad) });
    }
    tareas.push({
      bloque: id, origen: 'recurso', posicion,
      plantilla: fichaModelo(b),
      contenido_generado: {
        formato: rec.formato,
        titulo: rec.titulo,
        subtema: (rec.subtemas_que_cubre || []).join(' / '),
        elementos: rec.contenido || [],
        complementos,
        descripcion: rec.descripcion || '',
        ...(conActividad ? { actividad: rec.actividad } : {})
      }
    });
  });

  const ev = g.evaluacion;
  if (ev) {
    const evIa = ia.evaluacion || {};
    anexo.push({ titulo: 'Evaluación ' + limpio(ev.tipo).toLowerCase() + ' del tema', texto: textoEvaluacion(ev, evIa) });
  }

  // Todos los marcadores de los bloques usados: los que el modelo no llene se dejan vacíos al final.
  const marcadores = Object.keys(bloques).flatMap(id => {
    const b = cat.bloques[id];
    return [...b.campos.map(c => c[0]), ...b.tablas.flatMap(t => t[3].map(c => c[0]))];
  });

  return {
    json: {
      ...j,
      advertencias: [...(j.advertencias || []), ...advertencias],
      nivel_plantilla: nivel,
      plantilla_id: cat.plantilla,
      carpeta_id: carpeta.id,
      nombre_copia: 'Guion_U' + j.unidad + '_T' + j.tema,
      relleno: {
        valores,
        bloques,
        // Tablas de los bloques usados: id → { columnas (marcadores en orden), titulos, min, max, opcional }.
        tablas_plantilla: Object.fromEntries(Object.keys(bloques).flatMap(id => cat.bloques[id].tablas.map(([tid, min, max, columnas, , opcional]) =>
          [tid, { columnas: columnas.map(c => c[0]), titulos: columnas.map(c => c[1]), min, max, opcional: opcional || null }]))),
        opcionales_plantilla: Object.keys(bloques).flatMap(id => cat.bloques[id].opcionales.map(([id2, , inicio, fin]) => ({ id: id2, inicio, fin }))),
        marcadores,
        anexo,
        recursos: g.recursos.length
      },
      tareas
    },
    pairedItem: { item: i }
  };
});

// Nodo Code: «Conservar guion y copia4» · Modo: Run Once for Each Item
// Conserva los datos del tema (ya con los campos de la plantilla del nivel) y agrega la copia que devolvió
// «Copiar plantilla de guion5».
const tema = $('Reunir campos de plantilla').all()[$itemIndex].json;
const copia = $input.item.json;
if (!copia.id) throw new Error('Google Drive no devolvió el ID de la copia del guion del tema ' + tema.tema + '.');
return {
  json: {
    ...tema,
    documento: {
      id: copia.id,
      nombre: copia.name || tema.nombre_copia,
      url: copia.webViewLink || 'https://docs.google.com/document/d/' + copia.id + '/edit'
    }
  }
};

// Nodo Code: «Preparar estructura del guion4» · Modo: Run Once for All Items
// Recibe la copia de la plantilla del nivel («Leer copia del guion4», Docs API) y arma las solicitudes que cambian su FORMA:
//   - borra los bloques de recurso que el tema no usa (de <<INICIO_Rnn>> a <<FIN_Rnn>>, con su tabla);
//   - dentro de la tabla de cada recurso, borra las partes opcionales que no aplican (filas <<Rnn_INICIO_X>> … <<Rnn_FIN_X>>)
//     y, en las que se conservan, solo las dos filas de marca;
//   - repite el grupo de filas de cada elemento (escena, nodo, hito, diapositiva…) tantas veces como elementos haya.
// El texto se escribe después, en «Preparar relleno del guion4», porque estas solicitudes mueven los índices.
// Se aplica de la posición más alta a la más baja (y, dentro de una tabla, de la fila más baja a la más alta).

const SIN_CAMBIOS = { replaceAllText: { containsText: { text: '<<__sin_cambios__>>', matchCase: true }, replaceText: '' } };
const textoParrafo = el => (el.paragraph?.elements || []).map(e => e.textRun?.content || '').join('');
const textoFila = fila => (fila.tableCells || []).map(c => (c.content || []).map(textoParrafo).join('')).join('');

return $input.all().map((item, i) => {
  const base = $('Conservar guion y copia').all()[i].json;
  const contenido = (item.json.body && item.json.body.content) || [];
  if (!contenido.length) throw new Error('No se pudo leer la copia del guion del tema ' + base.tema + '.');
  const { bloques, tablas, opcionales, tablas_plantilla } = base.relleno;
  const advertencias = [...(base.advertencias || [])];
  const ops = [];

  // ---- bloques de recurso ----
  const marcas = {};
  contenido.forEach(el => {
    const m = el.paragraph && /^<<(INICIO|FIN)_R(\d{2})>>$/.exec(textoParrafo(el).trim());
    if (m) (marcas[m[2]] = marcas[m[2]] || {})[m[1]] = el;
  });
  const finCuerpo = contenido[contenido.length - 1].endIndex;
  const borrados = [];
  for (const [id, mk] of Object.entries(marcas)) {
    if (!mk.INICIO || !mk.FIN) { advertencias.push('La plantilla tiene <<INICIO_R' + id + '>> o <<FIN_R' + id + '>> sin su pareja.'); continue; }
    if (bloques[id]) continue;
    // El último salto de línea del documento no se puede borrar.
    const fin = mk.FIN.endIndex >= finCuerpo ? mk.FIN.endIndex - 1 : mk.FIN.endIndex;
    borrados.push([mk.INICIO.startIndex, fin]);
    ops.push({ p: mk.INICIO.startIndex, f: 0, req: { deleteContentRange: { range: { startIndex: mk.INICIO.startIndex, endIndex: fin } } } });
  }
  for (const id of Object.keys(bloques)) if (!marcas[id]) advertencias.push('La plantilla no tiene el bloque R' + id + '.');
  const enBorrado = idx => borrados.some(([a, b]) => idx >= a && idx < b);

  // ---- filas de cada tabla de recurso ----
  for (const el of contenido) {
    if (!el.table || enBorrado(el.startIndex)) continue;
    const filas = (el.table.tableRows || []).map(textoFila);
    if (!filas.some(t => /<<R\d{2}_/.test(t))) continue; // información general u otra tabla sin bloque
    const celda = rowIndex => ({ tableCellLocation: { tableStartLocation: { index: el.startIndex }, rowIndex, columnIndex: 0 } });
    const filaOps = [];
    const filasBorradas = new Set();

    // Actividad en un bloque sin campos de actividad: cuatro filas nuevas al final de su tabla (banda + tres campos).
    // Se piden primero (r mayor) para que queden después de las filas que agregan las tablas repetibles.
    const idBloque = ((/<<R(\d{2})_/.exec(filas.find(t => /<<R\d{2}_/.test(t)) || '')) || [])[1];
    const extra = idBloque && (base.relleno.actividad_extra || {})[idBloque];
    if (extra && bloques[idBloque]) {
      for (let x = 0; x < 4; x++) filaOps.push({ r: filas.length, req: { insertTableRow: { ...celda(filas.length - 1), insertBelow: true } } });
    }

    for (const o of base.relleno.opcionales_plantilla || []) {
      const a = filas.findIndex(t => t.trim() === '<<' + o.inicio + '>>');
      const b = filas.findIndex(t => t.trim() === '<<' + o.fin + '>>');
      if (a < 0 || b < 0) continue;
      const rango = opcionales[o.id] ? [a, b] : Array.from({ length: b - a + 1 }, (_, k) => a + k);
      rango.forEach(r => filasBorradas.add(r));
    }
    filasBorradas.forEach(r => filaOps.push({ r, req: { deleteTableRow: celda(r) } }));

    for (const [tid, def] of Object.entries(tablas_plantilla)) {
      const r = filas.findIndex(t => t.includes('<<' + def.columnas[0] + '>>'));
      if (r < 0 || filasBorradas.has(r)) continue;
      const k = def.columnas.length;
      const n = Math.max((tablas[tid] || []).length, 1);
      for (let x = 0; x < (n - 1) * k; x++) filaOps.push({ r: r + k - 1, req: { insertTableRow: { ...celda(r + k - 1), insertBelow: true } } });
    }
    filaOps.sort((a, b) => b.r - a.r).forEach((o, n) => ops.push({ p: el.startIndex, f: n + 1, req: o.req }));
  }

  ops.sort((a, b) => b.p - a.p || a.f - b.f);
  return {
    json: { ...base, estructura_requests: ops.length ? ops.map(o => o.req) : [SIN_CAMBIOS], advertencias },
    pairedItem: { item: i }
  };
});

// Nodo Code: «Preparar relleno del guion4» · Modo: Run Once for All Items
// Recibe la copia ya con su forma final («Leer copia estructurada4») y arma las solicitudes que escriben el texto:
//   - anexo al final del documento (recursos sin bloque, actividades y evaluación del tema), si lo hay;
//   - cada elemento de las tablas repetibles: el primero reemplaza los marcadores de la fila modelo; los demás se escriben
//     en las filas agregadas (título a la izquierda, contenido a la derecha);
//   - campos únicos e información general: replaceAllText;
//   - marcadores que quedaron sin contenido y marcas <<INICIO_Rnn>>/<<FIN_Rnn>> de los bloques conservados: se vacían.
// Las celdas se escriben de la posición más alta a la más baja para que los índices calculados sigan siendo válidos.

const ANEXO_EN_TABLA = true;   // false: el anexo vuelve a ir todo como texto
const AZUL_CLARO = { red: 0.788, green: 0.839, blue: 0.890 };   // C9D6E3: primer campo de cada elemento
const AZUL_OSCURO = { red: 0.10980392, green: 0.25490198, blue: 0.38431373 };   // 1C4161: títulos de bloque y bandas de sección
const GRIS_CLARO = { red: 0.929, green: 0.949, blue: 0.969 };   // EDF2F7: títulos de campo
const textoParrafo = el => (el.paragraph?.elements || []).map(e => e.textRun?.content || '').join('');
const textoFila = fila => (fila.tableCells || []).map(c => (c.content || []).map(textoParrafo).join('')).join('');
const reemplazar = (marcador, valor) => ({
  replaceAllText: { containsText: { text: '<<' + marcador + '>>', matchCase: true }, replaceText: String(valor ?? '') }
});
const estilo = (inicio, fin, negrita, puntos) => ({
  updateTextStyle: {
    range: { startIndex: inicio, endIndex: fin },
    textStyle: { bold: negrita, fontSize: { magnitude: puntos, unit: 'PT' }, weightedFontFamily: { fontFamily: 'Arial' } },
    fields: 'bold,fontSize,weightedFontFamily'
  }
});
const negrita = (inicio, fin) => ({ updateTextStyle: { range: { startIndex: inicio, endIndex: fin }, textStyle: { bold: true }, fields: 'bold' } });

// Dónde escribir dentro de la celda: sobre el marcador (fila modelo) o al inicio de la celda vacía (fila agregada).
function destinoEnCelda(celda, marcador) {
  for (const bloque of (celda && celda.content) || []) {
    for (const e of (bloque.paragraph && bloque.paragraph.elements) || []) {
      const t = e.textRun && e.textRun.content;
      if (marcador && t && t.includes(marcador) && Number.isInteger(e.startIndex)) return { p: e.startIndex + t.indexOf(marcador), borrar: marcador.length };
    }
  }
  const primero = celda && celda.content && celda.content[0];
  return primero && Number.isInteger(primero.startIndex) ? { p: primero.startIndex, borrar: 0 } : null;
}

// Etiquetas al inicio de línea dentro de un valor («Narración:», «Pregunta 2:», «A)»…) van en negrita.
function rangosNegrita(texto) {
  const rangos = [];
  let pos = 0;
  for (const linea of texto.split('\n')) {
    const m = /^[¿¡]?[A-ZÁÉÍÓÚÑ][^:\n.?!]{0,45}:/.exec(linea) || /^(?:[A-Da-e]|\d{1,2})[.)](?=\s)/.exec(linea);
    if (m && m[0].split(/\s+/).length <= 6) rangos.push([pos, pos + m[0].length]);
    pos += linea.length + 1;
  }
  return rangos;
}

return $input.all().map((item, i) => {
  const base = $('Preparar estructura del guion').all()[i].json;
  const contenido = (item.json.body && item.json.body.content) || [];
  const { valores, campos, tablas, tablas_plantilla, bloques, marcadores, anexo } = base.relleno;
  const enAnexo = a => /^Recurso \d+ · /.test(a) && /su guion va en el anexo del documento/.test(a);
  const advertencias = [...(base.advertencias || [])].filter(a => !(ANEXO_EN_TABLA && enAnexo(a)));
  const primeros = [];
  const escrituras = [];
  const reemplazos = [];

  // ---- anexo al final (va primero: queda detrás de todo y no mueve los índices de lo demás) ----
  // Los recursos sin bloque propio en la plantilla se escriben en una tabla de dos columnas (campo | contenido), como los
  // demás recursos; las actividades y la evaluación del tema siguen como texto. Con ANEXO_EN_TABLA = false todo va como texto.
  if (anexo && anexo.length && contenido.length) {
    const limpio = x => String(x ?? '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').trim();
    const jTema = (($('Armar guion').all()[i] || {}).json) || {};
    const recursosGuion = (jTema.guion && jTema.guion.recursos) || [];
    const iaTema = (($('Reensamblar recursos ajustados').all()[i] || {}).json) || {};
    const recursosIa = ((iaTema.output || iaTema).recursos) || [];
    const ANCHO_CAMPO = 129.6;   // mismas medidas de las tablas de la plantilla
    const ANCHO_VALOR = 302.4;

    // Los recursos sin bloque en la plantilla se escriben como un bloque más: título «Recurso NN · formato» y una tabla campo | contenido
    // con el estilo de la plantilla; lo demás (actividades sueltas, evaluación) va en un anexo de texto. Todo se arma como una lista
    // de bloques (texto o tabla) en orden de lectura y se inserta del último al primero, todos en el mismo índice (el final del
    // documento): cada inserción empuja hacia abajo lo ya escrito, así ningún índice depende de cuánto mide lo que va después.
    // Dentro de una tabla, el índice del párrafo de cada celda se calcula sobre la tabla vacía y las celdas se escriben de la más
    // alta a la más baja.
    const bloquesAnexo = [];
    let tramo = '\n';
    let rangosTramo = [];
    const agregar = (t, tipo) => {
      const ini = tramo.length;
      tramo += String(t || '') + '\n';
      rangosTramo.push([ini, ini + String(t || '').length, tipo]);
    };
    const cerrarTexto = () => {
      if (tramo) bloquesAnexo.push({ texto: tramo, rangos: rangosTramo });
      tramo = '';
      rangosTramo = [];
    };
    const agregarTabla = filas => {
      // El título va pegado a la tabla: su salto de línea es el que Docs agrega antes de la tabla.
      if (tramo.endsWith('\n')) tramo = tramo.slice(0, -1);
      cerrarTexto();
      bloquesAnexo.push({ filas });
      tramo = '\n';   // párrafo de separación después de la tabla
    };
    const COLOR_TITULO = { color: { rgbColor: AZUL_OSCURO } };
    const escribirTexto = (texto, rangos, p) => {
      primeros.push({ insertText: { location: { index: p }, text: texto } });
      primeros.push(estilo(p, p + texto.length, false, 10));
      primeros.push({ updateParagraphStyle: { range: { startIndex: p, endIndex: p + texto.length }, paragraphStyle: { namedStyleType: 'NORMAL_TEXT' }, fields: 'namedStyleType' } });
      rangos.forEach(([x, y, tipo]) => {
        if (tipo === 'titulo') primeros.push(estilo(p + x, p + y, true, 14));
        if (tipo === 'subtitulo') primeros.push(estilo(p + x, p + y, true, 11));
        if (tipo === 'bloque') {
          primeros.push({ updateParagraphStyle: { range: { startIndex: p + x, endIndex: p + y }, paragraphStyle: { namedStyleType: 'HEADING_1', spaceBelow: { magnitude: 4, unit: 'PT' }, keepWithNext: true }, fields: 'namedStyleType,spaceBelow,keepWithNext' } });
          primeros.push({ updateTextStyle: { range: { startIndex: p + x, endIndex: p + y }, textStyle: { bold: true, foregroundColor: COLOR_TITULO, fontSize: { magnitude: 15, unit: 'PT' }, weightedFontFamily: { fontFamily: 'Arial' } }, fields: 'bold,foregroundColor,fontSize,weightedFontFamily' } });
        }
        if (tipo === 'texto') rangosNegrita(texto.slice(x, y)).forEach(([u, v]) => primeros.push(negrita(p + x + u, p + x + v)));
      });
    };
    const RELLENO_CELDA = { paddingLeft: { magnitude: 5, unit: 'PT' }, paddingRight: { magnitude: 5, unit: 'PT' }, paddingTop: { magnitude: 3.5, unit: 'PT' }, paddingBottom: { magnitude: 3.5, unit: 'PT' } };
    const escribirTabla = (filas, p) => {
      const R = filas.length;
      const C = 2;
      const inicioTabla = p + 1;
      const parrafo = (r, c) => p + 4 + r * (1 + 2 * C) + 2 * c;
      primeros.push({ insertTable: { location: { index: p }, rows: R, columns: C } });
      primeros.push({ updateTableColumnProperties: { tableStartLocation: { index: inicioTabla }, columnIndices: [0], tableColumnProperties: { widthType: 'FIXED_WIDTH', width: { magnitude: ANCHO_CAMPO, unit: 'PT' } }, fields: 'width,widthType' } });
      primeros.push({ updateTableColumnProperties: { tableStartLocation: { index: inicioTabla }, columnIndices: [1], tableColumnProperties: { widthType: 'FIXED_WIDTH', width: { magnitude: ANCHO_VALOR, unit: 'PT' } }, fields: 'width,widthType' } });
      filas.forEach((f, r) => {
        const fondoIzq = f.tipo === 'banda' ? AZUL_OSCURO : f.tipo === 'elemento' ? AZUL_CLARO : GRIS_CLARO;
        [0, 1].forEach(c => {
          const conFondo = c === 0 || f.tipo === 'banda';
          primeros.push({ updateTableCellStyle: {
            tableRange: { tableCellLocation: { tableStartLocation: { index: inicioTabla }, rowIndex: r, columnIndex: c }, rowSpan: 1, columnSpan: 1 },
            tableCellStyle: { ...RELLENO_CELDA, ...(conFondo ? { backgroundColor: { color: { rgbColor: fondoIzq } } } : {}) },
            fields: (conFondo ? 'backgroundColor,' : '') + 'paddingLeft,paddingRight,paddingTop,paddingBottom'
          } });
        });
      });
      const celdas = [];
      filas.forEach((f, r) => {
        if (f.campo) celdas.push({ r, c: 0, texto: f.campo, titulo: true, banda: f.tipo === 'banda' });
        if (f.valor) celdas.push({ r, c: 1, texto: f.valor, titulo: false, banda: false });
      });
      celdas.sort((x, y) => parrafo(y.r, y.c) - parrafo(x.r, x.c));
      celdas.forEach(({ r, c, texto, titulo, banda }) => {
        const q = parrafo(r, c);
        primeros.push({ insertText: { location: { index: q }, text: texto } });
        primeros.push(estilo(q, q + texto.length, titulo, titulo ? 9 : 10));
        if (banda) primeros.push({ updateTextStyle: { range: { startIndex: q, endIndex: q + texto.length }, textStyle: { foregroundColor: { color: { rgbColor: { red: 1, green: 1, blue: 1 } } } }, fields: 'foregroundColor' } });
        if (!titulo) rangosNegrita(texto).forEach(([x, y]) => primeros.push(negrita(q + x, q + y)));
      });
    };

    const filasRecurso = (rec, complementos, posicion) => {
      const filas = [];
      const fila = (campo, valor, tipo) => { const v = limpio(valor); if (v) filas.push({ campo, valor: v, tipo: tipo || 'campo' }); };
      const banda = titulo => filas.push({ campo: titulo, valor: '', tipo: 'banda' });
      fila('Código del recurso', 'U' + jTema.unidad + '-T' + jTema.tema + '-R' + posicion);
      fila('Título del recurso', rec.titulo);
      fila('Subtema', (rec.subtemas_que_cubre || []).join('\n'));
      if ((rec.contenido || []).length) banda('Contenido del recurso');
      (rec.contenido || []).forEach((s, n) => {
        fila('Elemento ' + (n + 1), limpio(s.rotulo) || 'Elemento ' + (n + 1), 'elemento');
        fila('Texto en pantalla', s.texto_visible);
        fila('Respaldo de producción', s.texto);
        fila('Recurso visual', s.visual);
      });
      if (complementos.length) banda('Complementos');
      complementos.forEach(c => fila(limpio(c.rotulo) || 'Complemento', c.texto));
      fila('Descripción para producción', rec.descripcion);
      if (limpio(rec.actividad)) { banda('Actividad de autoaprendizaje'); fila('Actividad', rec.actividad); }
      return filas;
    };

    // Recursos sin bloque: cada uno como un bloque más (numeración a continuación de los bloques de la plantilla); el resto, al anexo.
    const otras = [];
    let numeroBloque = 14;
    anexo.forEach(a => {
      const m = ANEXO_EN_TABLA && /^Recurso (\d+) · /.exec(String(a.titulo || ''));
      const posicion = m ? Number(m[1]) : 0;
      const rec = m ? (recursosGuion.find(x => Number(x.posicion) === posicion) || recursosGuion[posicion - 1]) : null;
      if (rec) {
        const recIa = recursosIa.find(x => Number(x.posicion) === posicion) || {};
        const complementos = (Array.isArray(recIa.complementos) ? recIa.complementos : []).filter(c => c && limpio(c.texto));
        const filas = filasRecurso(rec, complementos, posicion);
        if (filas.length) {
          agregar('Recurso ' + String(numeroBloque).padStart(2, '0') + ' · ' + (limpio(rec.formato) || 'Recurso'), 'bloque');
          agregarTabla(filas);
          numeroBloque++;
          return;
        }
      }
      otras.push(a);
    });
    if (otras.length) {
      agregar('Anexo del tema', 'titulo');
      agregar('Contenidos que no tienen un bloque propio en la plantilla de este nivel.', 'nota');
      otras.forEach(a => { agregar(a.titulo, 'subtitulo'); agregar(a.texto, 'texto'); });
    }
    cerrarTexto();
    const inicioAnexo = contenido[contenido.length - 1].endIndex - 1;
    [...bloquesAnexo].reverse().forEach(b => { if (b.filas) escribirTabla(b.filas, inicioAnexo); else escribirTexto(b.texto, b.rangos, inicioAnexo); });
  }

  // ---- tablas repetibles ----
  for (const [tid, def] of Object.entries(tablas_plantilla)) {
    const elementos = tablas[tid] || [];
    const k = def.columnas.length;
    let encontrada = null;
    for (const el of contenido) {
      if (!el.table) continue;
      const r = (el.table.tableRows || []).findIndex(f => textoFila(f).includes('<<' + def.columnas[0] + '>>'));
      if (r >= 0) { encontrada = { el, r }; break; }
    }
    if (!encontrada) continue; // su parte opcional o su bloque se borró
    if (!elementos.length) continue; // los marcadores se vacían al final
    const filas = encontrada.el.table.tableRows || [];
    const inicioTabla = encontrada.el.startIndex;
    elementos.forEach((valoresElemento, e) => {
      def.columnas.forEach((m, c) => {
        const rowIndex = encontrada.r + e * k + c;
        const fila = filas[rowIndex];
        if (!fila) { advertencias.push('La tabla ' + tid + ' quedó con menos filas que elementos (' + elementos.length + ').'); return; }
        const valor = String(valoresElemento[c] ?? '');
        const reqs = [];
        const destValor = destinoEnCelda((fila.tableCells || [])[1], e === 0 ? '<<' + m + '>>' : null);
        if (destValor) {
          const r = [];
          if (destValor.borrar) r.push({ deleteContentRange: { range: { startIndex: destValor.p, endIndex: destValor.p + destValor.borrar } } });
          if (valor) {
            r.push({ insertText: { location: { index: destValor.p }, text: valor } });
            r.push(estilo(destValor.p, destValor.p + valor.length, false, 10));
            rangosNegrita(valor).forEach(([a, b]) => r.push(negrita(destValor.p + a, destValor.p + b)));
          }
          if (r.length) escrituras.push({ p: destValor.p, reqs: r });
        }
        if (e > 0) {
          // Fila agregada: título del campo a la izquierda y color de fondo como en la plantilla.
          const destTitulo = destinoEnCelda((fila.tableCells || [])[0], null);
          if (destTitulo) {
            const titulo = def.titulos[c];
            escrituras.push({ p: destTitulo.p, reqs: [
              { insertText: { location: { index: destTitulo.p }, text: titulo } },
              estilo(destTitulo.p, destTitulo.p + titulo.length, true, 9),
              { updateTableCellStyle: {
                tableRange: { tableCellLocation: { tableStartLocation: { index: inicioTabla }, rowIndex, columnIndex: 0 }, rowSpan: 1, columnSpan: 1 },
                tableCellStyle: { backgroundColor: { color: { rgbColor: c === 0 ? AZUL_CLARO : GRIS_CLARO } } },
                fields: 'backgroundColor'
              } }
            ] });
          }
        }
      });
    });
  }
  // ---- actividad escrita dentro de un bloque sin campos de actividad (cuatro filas agregadas al final de su tabla) ----
  for (const [id, ex] of Object.entries(base.relleno.actividad_extra || {})) {
    if (!bloques[id]) continue;
    const tabla = contenido.find(el => el.table && (el.table.tableRows || []).some(f => textoFila(f).includes('<<R' + id + '_CODIGO>>')));
    const filasT = tabla ? (tabla.table.tableRows || []) : [];
    if (filasT.length < 4) { advertencias.push('Recurso ' + ex.posicion + ': no se pudo escribir su actividad dentro del bloque.'); continue; }
    const r0 = filasT.length - 4;
    const dadosAct = ex.campos.map(c => String((campos || {})[c.marcador] ?? '').trim());
    if (!dadosAct.some(Boolean)) dadosAct[0] = String(ex.texto || '').trim();   // el modelo no la estructuró: va el texto de la unidad
    const BLANCO = { red: 1, green: 1, blue: 1 };
    const estiloCelda = (r, c, fondo) => ({ updateTableCellStyle: {
      tableRange: { tableCellLocation: { tableStartLocation: { index: tabla.startIndex }, rowIndex: r0 + r, columnIndex: c }, rowSpan: 1, columnSpan: 1 },
      tableCellStyle: { backgroundColor: { color: { rgbColor: fondo } } }, fields: 'backgroundColor'
    } });
    const textoAct = (r, c, texto, negritaTitulo, puntos, color, reqsExtra) => {
      const dest = destinoEnCelda((filasT[r0 + r].tableCells || [])[c], null);
      if (!dest) return;
      const reqs = [...reqsExtra];
      if (texto) {
        reqs.push({ insertText: { location: { index: dest.p }, text: texto } });
        reqs.push(estilo(dest.p, dest.p + texto.length, negritaTitulo, puntos));
        reqs.push({ updateTextStyle: { range: { startIndex: dest.p, endIndex: dest.p + texto.length }, textStyle: { foregroundColor: { color: { rgbColor: color } } }, fields: 'foregroundColor' } });
        if (!negritaTitulo) rangosNegrita(texto).forEach(([x, y]) => reqs.push(negrita(dest.p + x, dest.p + y)));
      }
      if (reqs.length) escrituras.push({ p: dest.p, reqs });
    };
    // banda
    textoAct(0, 0, 'Actividad de autoaprendizaje', true, 9, BLANCO, [estiloCelda(0, 0, AZUL_OSCURO)]);
    textoAct(0, 1, '', false, 10, BLANCO, [estiloCelda(0, 1, AZUL_OSCURO)]);
    // consigna, respuesta, retroalimentación
    ex.campos.forEach((c, k) => {
      textoAct(k + 1, 0, c.etiqueta, true, 9, { red: 0, green: 0, blue: 0 }, [estiloCelda(k + 1, 0, GRIS_CLARO)]);
      textoAct(k + 1, 1, dadosAct[k], false, 10, { red: 0, green: 0, blue: 0 }, [estiloCelda(k + 1, 1, BLANCO)]);
    });
  }
  escrituras.sort((a, b) => b.p - a.p);

  // ---- campos únicos, información general y limpieza ----
  const dados = { ...campos, ...valores };
  for (const [m, v] of Object.entries(dados)) reemplazos.push(reemplazar(m, v));
  for (const m of marcadores || []) if (!(m in dados)) reemplazos.push(reemplazar(m, ''));
  for (const id of Object.keys(bloques)) reemplazos.push(reemplazar('INICIO_R' + id, ''), reemplazar('FIN_R' + id, ''));

  return {
    json: { ...base, relleno_requests: [...primeros, ...escrituras.flatMap(x => x.reqs), ...reemplazos], advertencias },
    pairedItem: { item: i }
  };
});

// Nodo Code: «Normalizar hoja RED» · Modo: Run Once for All Items
// Va entre «Leer estructura RED» y «Armar estructura RED».
// La API devuelve todas las pestañas de la hoja "Estructura RED - <nivel>". «Armar estructura RED» busca las pestañas
// por nombre (OVIs, OVAs, Actividades, Evaluaciones), pero las hojas actuales usan otros nombres (por ejemplo «RED»
// para todos los recursos). Aquí cada pestaña se reconoce por su fila de encabezados y se entrega con el nombre que
// espera el nodo siguiente, en el mismo formato de batchGet (valueRanges).

const respuesta = $input.first().json || {};
if (respuesta.error || !Array.isArray(respuesta.sheets)) return [{ json: respuesta }];

const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const recursos = [];
const otras = {};
for (const hoja of respuesta.sheets) {
  const titulo = (hoja.properties && hoja.properties.title) || '';
  const filas = ((hoja.data && hoja.data[0] && hoja.data[0].rowData) || [])
    .map(f => (f.values || []).map(c => (c && c.formattedValue != null ? String(c.formattedValue) : '')));
  // El encabezado puede no ser la primera fila (algunas hojas traen antes el perfil del nivel).
  const cabeceras = filas.slice(0, 8).map(f => f.map(norm));
  const tiene = re => cabeceras.some(f => f.some(c => re.test(c)));
  if (!tiene(/^estructura/)) continue;
  if (tiene(/^recurso$/)) recursos.push({ titulo, filas });
  else if (tiene(/^actividad$|^h$/)) otras.Actividades = otras.Actividades || filas;
  else if (tiene(/evaluacion/)) otras.Evaluaciones = otras.Evaluaciones || filas;
}

// Si las pestañas ya se llaman OVIs/OVAs se respetan; si hay una sola (por ejemplo «RED»), sirve para ambas.
const porNombre = n => recursos.find(r => norm(r.titulo) === norm(n));
const ovis = porNombre('OVIs') || recursos[0];
const ovas = porNombre('OVAs') || recursos.find(r => r !== ovis) || ovis;

const valueRanges = [];
if (ovis) valueRanges.push({ range: 'OVIs!A1', values: ovis.filas });
if (ovas) valueRanges.push({ range: 'OVAs!A1', values: ovas.filas });
for (const [nombre, filas] of Object.entries(otras)) valueRanges.push({ range: nombre + '!A1', values: filas });

return [{
  json: {
    valueRanges,
    pestanas: respuesta.sheets.map(h => (h.properties && h.properties.title) || ''),
    ...(valueRanges.length ? {} : { error: { message: 'La hoja no tiene pestañas reconocibles (recursos, actividades o evaluaciones).' } })
  }
}];

// Nodo Code: «Completar requisitos RED» · Modo: Run Once for All Items
// Va después de «Armar estructura RED» y «Leer datos del Syllabus». Convierte el texto de la hoja "Estructura RED - <nivel>"
// en requisitos concretos que el modelo debe cumplir y que el control de calidad («Auditar borrador») verifica:
//   recursos[].reglas_formato          → cantidad exacta de elementos e interacciones del formato
//   recursos[].secciones_requeridas    → partes que van DENTRO del contenido (resumen, glosario… de una lectura; cierre de un podcast)
//   recursos[].complementos_requeridos → partes únicas FUERA de los elementos (subtítulo, nota explicativa, leyenda, cierre, duración…)
//   recursos[].actividad_requisitos    → ítems, categorías, instrucción, retroalimentación y duración de la actividad
//   presentacion.estructura_red        → presentación de 4 pantallas de la hoja (no un video)
//   evaluacion.requisitos              → preguntas, duración, intentos y escala de la hoja de evaluaciones
//   asignatura                         → datos de la asignatura para la presentación (modalidad, periodo y títulos de unidades del Syllabus)
// También deja en cada tema solo las advertencias que le corresponden.

const temas = $('Armar estructura RED').all();
const hoja = (() => { try { return $('Normalizar hoja RED').first().json; } catch (e) { return {}; } })();
const textoSyllabus = (() => {
  const j = ($input.first() || {}).json || {};
  return typeof j.data === 'string' && !j.error ? j.data.replace(/\r/g, '').replace(/^﻿/, '') : '';
})();

const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const plano = s => String(s ?? '').replace(/\s+/g, ' ').trim();
const aNum = s => Number(String(s).replace(/\.(?=\d{3}\b)/g, '').replace(',', '.'));
const R = '(\\d+(?:[.,]\\d+)?)\\s*(?:a|–|-|—)\\s*(\\d+(?:[.,]\\d+)?)';
const rango = (texto, re) => { const m = re.exec(texto); return m ? [aNum(m[1]), aNum(m[2])].sort((a, b) => a - b) : null; };
const conR = (prefijo, sufijo) => new RegExp(prefijo + R + sufijo, 'i');

function claveRecurso(nombre) {
  const n = norm(nombre);
  if (!n) return null;
  if (/infograf/.test(n)) return /interactiv/.test(n) ? 'infografia_interactiva' : 'infografia_estatica';
  if (/linea.*tiempo/.test(n)) return 'linea_tiempo';
  if (/diagrama.*flujo/.test(n)) return 'diagrama_flujo';
  if (/mapa.*conceptual/.test(n)) return 'mapa_conceptual';
  if (/micro ?lecci/.test(n)) return 'micro_leccion';
  if (/micro/.test(n)) return 'video_micro';
  if (/video/.test(n)) return /explicativ/.test(n) ? 'video_explicativo' : 'video_academico';
  if (/podcast/.test(n)) return 'podcast';
  if (/presentacion|multimedia/.test(n)) return 'presentacion_multimedia';
  if (/acordeon/.test(n)) return 'acordeon';
  if (/galeria/.test(n)) return 'galeria';
  if (/lectura/.test(n)) return 'lectura';
  if (/laboratorio/.test(n)) return 'laboratorio';
  return null;
}

// ---------- partes únicas por formato ----------
// si: la parte se exige solo cuando la estructura o la extensión de la hoja la mencionan.
// limite: etiqueta de la cifra en la columna Extensión (por ejemplo «Subtítulo: 10–20 palabras»).
const P = (nombre, si, indicacion, limite) => ({ nombre, si, indicacion, limite: limite || null });
const COMPLEMENTOS = {
  infografia_estatica: [P('Cierre', /cierre|conclusi/, 'Recomendación, conclusión o pregunta de comprobación, separada de los bloques.')],
  infografia_interactiva: [
    P('Subtítulo', /subt[ií]tulo/, 'Frase que contextualiza el tema, debajo del título.', /subt[ií]tulo/),
    P('Idea central', /idea central/, 'Idea central del tema explicada en una o dos frases.'),
    P('Cierre', /cierre|s[ií]ntesis/, 'Síntesis o recomendación práctica final, separada de los bloques.')
  ],
  diagrama_flujo: [
    P('Nota explicativa', /nota/, 'Recomendación o error frecuente del proceso representado.', /nota/),
    P('Leyenda de símbolos', /leyenda/, 'Cada símbolo usado en el diagrama y su significado: óvalo (inicio/fin), rectángulo (proceso), rombo (decisión), flecha (secuencia).')
  ],
  mapa_conceptual: [
    P('Palabras de enlace', /enlace|conexi/, 'Cada conexión del mapa en su línea: «Concepto A → palabra de enlace → Concepto B». Una por cada relación del mapa.'),
    P('Pregunta de cierre', /cerrar con una pregunta|pregunta de relaci/, 'Pregunta que obligue a relacionar conceptos del mapa, con su respuesta esperada.')
  ],
  video_micro: [P('Pregunta de comprensión', /pregunta de comprensi|reto breve/, 'Pregunta o reto breve para el final del video, con su respuesta esperada.')],
  video_explicativo: [P('Pregunta de comprobación', /pregunta de comprobaci/, 'Pregunta de comprobación del final del video, con su respuesta esperada.')],
  video_academico: [P('Pregunta de reflexión', /pregunta de reflexi|transferencia/, 'Pregunta de reflexión o transferencia del cierre del video.')],
  galeria: [P('Cierre', /pregunta de observaci|cerrar con|cierre/, 'Pregunta de observación o conclusión breve sobre la galería.')],
  acordeon: [P('Instrucción de uso', /instrucci/, 'Indicación breve de cómo abrir y recorrer los paneles.')],
  linea_tiempo: [
    P('Introducción', /introducci/, 'Introducción breve a la línea de tiempo.', /introducci/),
    P('Síntesis', /s[ií]ntesis/, 'Síntesis crítica de la secuencia.', /s[ií]ntesis/)
  ]
};
// Partes que van como secciones del contenido (se leen dentro del recurso y cuentan en su extensión).
const SECCIONES = {
  lectura: [
    P('Resumen', /resumen/, 'Resumen inicial de la lectura.', /resumen/),
    P('Introducción', /introducci/, 'Introducción al tema de la lectura.'),
    P('Recuadro destacado', /recuadro/, 'Definición, caso o ejemplo aplicado destacado en un recuadro independiente.'),
    P('Glosario', /glosario|hotspot/, 'Términos clave numerados: «1. Término: definición.»'),
    P('Conclusión', /conclusi/, 'Conclusión de la lectura.'),
    P('Referencias', /referencias/, 'IDs de la bibliografía entre corchetes, por ejemplo [U1-B1] [U1-B2].')
  ],
  podcast: [
    P('Cortinilla de entrada', /cortinilla/, 'Entrada sonora con presentación del programa; aquí sí puede ir música.'),
    P('Cierre', /cierre/, 'Cierre con «Idea clave 1:», «Idea clave 2:», «Idea clave 3:» y una pregunta final para el estudiante; aquí sí puede ir música.')
  ]
};

// Cifra «Etiqueta: a–b unidad», «Etiqueta (a–b unidad)» o «Etiqueta: máximo N unidad» de la columna Extensión o Estructura.
function cifra(texto, etiqueta, unidad) {
  const t = plano(texto);
  const u = unidad || '(palabras|caracteres|t[eé]rminos|minutos)';
  const re1 = new RegExp('(' + etiqueta.source + ')[^:•()\\n]{0,40}[:(]\\s*' + R + '\\s*' + u, 'i');
  const m1 = re1.exec(t);
  if (m1) {
    const k = m1.length;
    return { min: aNum(m1[k - 3]), max: aNum(m1[k - 2]), unidad: norm(m1[k - 1]).startsWith('caracter') ? 'caracteres' : norm(m1[k - 1]).startsWith('minut') ? 'minutos' : norm(m1[k - 1]).startsWith('termin') ? 'términos' : 'palabras' };
  }
  const re2 = new RegExp('(' + etiqueta.source + ')[^:•\\n]{0,40}:\\s*(?:m[aá]x(?:imo)?\\.?|hasta)\\s*(\\d+)\\s*' + u, 'i');
  const m2 = re2.exec(t);
  if (m2) {
    const k = m2.length;
    return { min: null, max: aNum(m2[k - 2]), unidad: norm(m2[k - 1]).startsWith('caracter') ? 'caracteres' : 'palabras' };
  }
  return null;
}

function requisitosFormato(r) {
  const er = r.estructura_red;
  if (!er) return { reglas_formato: null, secciones_requeridas: [], complementos_requeridos: [] };
  const clave = claveRecurso(r.formato);
  const texto = plano(er.estructura) + ' ' + plano(er.extension);
  const nt = norm(texto);
  const L = er.limites || {};
  const duracion = rango(plano(er.extension), conR('(?:duraci[oó]n|tiempo|lectura\\/interacci[oó]n estimada|interacci[oó]n estimada)[^:•]{0,30}:\\s*', '\\s*minutos')) || L.duracion_min || null;

  const construir = lista => (lista || []).filter(p => p.si.test(nt) || p.si.test(texto.toLowerCase())).map(p => {
    const c = p.limite ? cifra(texto, p.limite) : null;
    return { nombre: p.nombre, indicacion: p.indicacion, min: c ? c.min : null, max: c ? c.max : null, unidad: c ? c.unidad : null };
  });
  const secciones = construir(SECCIONES[clave]);
  const glosario = secciones.find(s => s.nombre === 'Glosario');
  if (glosario) {
    const t = rango(texto, conR('', '\\s*t[eé]rminos'));
    if (t) { glosario.min = t[0]; glosario.max = t[1]; glosario.unidad = 'términos'; }
  }
  const complementos = construir(COMPLEMENTOS[clave]);
  if (duracion && clave !== 'podcast' && !/^video/.test(clave || '')) {
    complementos.push({ nombre: 'Duración estimada', indicacion: 'Escriba «Duración estimada: N minutos», con N entre ' + duracion[0] + ' y ' + duracion[1] + '.', min: duracion[0], max: duracion[1], unidad: 'minutos' });
  }
  // La hoja pide una actividad de autoaprendizaje dentro del propio recurso; si el documento de la unidad no le asignó
  // actividad (recurso informativo), se escribe como complemento breve para no cambiar la matriz de recursos.
  if (r.tipo !== 'OVA' && /actividad de autoaprendizaje/.test(nt)) {
    complementos.push({ nombre: 'Actividad de autoaprendizaje', indicacion: 'Tres preguntas cerradas («Pregunta 1:»…) con opciones A) B) C) D), «Respuesta correcta:» y «Retroalimentación:» de 20 a 35 palabras.', min: null, max: null, unidad: null });
  }
  const interacciones = rango(texto, conR('', '\\s*(?:interacciones|preguntas integradas|interacciones o preguntas)'));
  const textoEscena = /m[aá]ximo\s*(\d+)\s*palabras por escena/i.exec(texto);
  return {
    reglas_formato: {
      clave,
      elementos: L.elementos || null,
      interacciones: /presentaci|multimedia/.test(norm(r.formato)) ? interacciones : null,
      palabras_pantalla_max: textoEscena ? Number(textoEscena[1]) : null,
      duracion
    },
    secciones_requeridas: secciones,
    complementos_requeridos: complementos
  };
}

// Etiquetas con que se cuentan los ítems de cada actividad.
const ITEMS = [
  [/pares/, 'pares', 'Par'],
  [/elementos/, 'elementos', 'Elemento'],
  [/preguntas/, 'preguntas', 'Pregunta'],
  [/t[eé]rminos/, 'términos', 'Término'],
  [/(?:decisiones|pasos)/, 'decisiones', 'Decisión'],
  [/alternativas/, 'alternativas', 'Opción']
];
function requisitosActividad(ae) {
  if (!ae) return null;
  const t = plano(ae.extension) || plano(ae.estructura);
  let items = null;
  for (const [re, nombre, etiqueta] of ITEMS) {
    const x = rango(t, new RegExp(R + '\\s*' + re.source + '(?![^•]*por)', 'i')) || rango(t, new RegExp(R + '\\s*' + re.source, 'i'));
    if (x) { items = { min: x[0], max: x[1], nombre, etiqueta }; break; }
  }
  const req = {
    actividad: ae.nombre_en_hoja,
    items,
    categorias: rango(t, conR('', '\\s*(?:categor[ií]as|zonas de destino)')),
    instruccion: rango(t, conR('instrucci[oó]n[^:•]{0,20}:\\s*', '\\s*palabras')),
    retroalimentacion: rango(t, conR('retroalimentaci[oó]n[^:•]{0,20}:\\s*', '\\s*palabras')),
    duracion: rango(t, conR('duraci[oó]n[^:•]{0,20}:\\s*', '\\s*minutos')) || rango(t, conR('', '\\s*minutos')),
    caso: rango(t, conR('caso[^:•]{0,20}:\\s*', '\\s*palabras'))
  };
  return Object.values(req).some((v, k) => k > 0 && v) ? req : null;
}

// ---------- presentación de la asignatura (fila «Diapositivas de presentación de la asignatura» de la hoja) ----------
const PRES_POR_DEFECTO = {
  estructura: 'Pantalla 1 — Bienvenida y contextualización: nombre de la asignatura, programa, periodo, créditos, modalidad y pregunta inicial sobre su importancia en el servicio. Pantalla 2 — ¿Qué aprenderás?: resultado de aprendizaje consignado en el syllabus, competencia del programa y relación con la práctica policial. Pantalla 3 — ¿Qué estudiarás?: mención de los títulos de las unidades. Pantalla 4 — ¿Cómo aprenderás?: recorrido por recursos, actividades y evaluaciones.',
  extension: '4 pantallas. Títulos: máximo 10 palabras. Texto visible recomendado: 35–60 palabras por pantalla. Interacciones: 1 exploración de unidades y navegación accesible. Información verificable: número de créditos, periodo o nivel, modalidad. Tiempo estimado de recorrido: 3–5 minutos. Los criterios de evaluación, fechas y porcentajes se incluirán solo después de su aprobación.'
};
const presHoja = (() => {
  for (const vr of (hoja.valueRanges || [])) {
    const filas = vr.values || [];
    const i = filas.findIndex(f => f.map(norm).includes('recurso') && f.map(norm).some(c => c.startsWith('estructura')));
    if (i < 0) continue;
    const cab = filas[i].map(norm);
    const iNom = cab.indexOf('recurso'), iEst = cab.findIndex(c => c.startsWith('estructura')), iExt = cab.findIndex(c => c.startsWith('extension'));
    const f = filas.slice(i + 1).find(x => /diapositivas|presentacion de la asignatura/.test(norm(x[iNom])));
    if (f) return { nombre: plano(f[iNom]), estructura: plano(f[iEst]), extension: plano(f[iExt]) };
  }
  return null;
})();
const presBase = presHoja || { nombre: 'Diapositivas de presentación de la asignatura', ...PRES_POR_DEFECTO };
const presTexto = presBase.estructura + ' ' + presBase.extension;
const presEstructura = {
  nombre_en_hoja: presBase.nombre,
  fuente: presHoja ? 'hoja de Drive' : 'estructura institucional por defecto',
  estructura: presBase.estructura,
  extension: presBase.extension,
  pantallas: (/(\d+)\s*pantallas/i.exec(presTexto) || [])[1] ? Number(/(\d+)\s*pantallas/i.exec(presTexto)[1]) : 4,
  titulo_max: Number((/T[ií]tulos?:\s*m[aá]ximo\s*(\d+)/i.exec(presTexto) || [])[1] || 10),
  texto_visible: rango(presTexto, conR('', '\\s*palabras por pantalla')) || [35, 60],
  duracion: rango(presTexto, conR('', '\\s*minutos')) || [3, 5]
};

// ---------- datos de la asignatura desde el Syllabus (texto plano exportado de Google Docs) ----------
const campoSyllabus = re => {
  const m = re.exec(textoSyllabus);
  return m ? plano(m[1]).replace(/\*/g, '') : null;
};
const unidadesSyllabus = (() => {
  const vistas = new Map();
  const re = /(?:^|\n)[ \t*]*Unidad\s*(?:Nro\.?|N[°ºo]\.?)\s*(\d+)[ \t*]*[\t\n]+[ \t*]*([^\t\n]{3,160})/gi;
  let m;
  while ((m = re.exec(textoSyllabus))) {
    const nombre = plano(m[2]).replace(/\*/g, '');
    if (!vistas.has(m[1]) && !/horas|indicador|bibliograf/i.test(nombre)) vistas.set(m[1], nombre);
  }
  return [...vistas].map(([numero, nombre]) => ({ numero: Number(numero), nombre })).sort((a, b) => a.numero - b.numero);
})();

// ---------- evaluaciones ----------
function requisitosEvaluacion(ev, estructuraRed) {
  if (!ev) return null;
  const tipo = /sumativ/i.test(ev.tipo) ? 'sumativa' : 'formativa';
  const spec = estructuraRed && estructuraRed.evaluaciones && estructuraRed.evaluaciones[tipo];
  if (!spec) return null;
  const ext = String(spec.extension || '');
  // Las condiciones de aplicación se copian literalmente de la hoja: no las escribe el modelo.
  const condiciones = ext.split(/\n|•/).map(plano).filter(Boolean)
    .filter(x => /duraci|intento|escala|calificaci|aprobatoria|retroalimentaci/i.test(x));
  return {
    tipo,
    preguntas: spec.preguntas || rango(ext, conR('', '\\s*preguntas')),
    duracion: rango(ext, conR('', '\\s*minutos')),
    condiciones_hoja: condiciones.map(x => x.replace(/[.;]$/, '') + '.')
  };
}

const PRESENTACION_EN_TEMA = 1;

return temas.map((item, idx) => {
  const j = item.json;
  const numero = j.tema && j.tema.numero;
  // Cada tema conserva las advertencias generales y las que hablan de él, no las de los demás temas.
  const advertencias = (j.advertencias_insumo || []).filter(a => {
    const nums = [...String(a).matchAll(/\b[Tt]ema\s+(\d+)\b/g)].map(m => Number(m[1]));
    return !nums.length || nums.includes(numero);
  });
  const recursos = (j.recursos || []).map(r => ({
    ...r,
    ...requisitosFormato(r),
    actividad_requisitos: r.tipo === 'OVA' ? requisitosActividad(r.actividad_estructura) : null
  }));
  const asignada = j.evaluacion && j.evaluacion.asignada;
  return {
    json: {
      ...j,
      advertencias_insumo: advertencias,
      asignatura: {
        nombre: j.general && j.general.asignatura,
        programa: j.general && j.general.programa,
        nivel_formacion: j.general && j.general.nivel_formacion,
        semestre_periodo: campoSyllabus(/Semestre\s*\/\s*periodo[ \t*]*[\t\n]+[ \t*]*([^\t\n]+)/i) || (j.general && j.general.semestre) || null,
        creditos: j.general && j.general.creditos,
        modalidad: campoSyllabus(/Modalidad[ \t*]*[\t\n]+[ \t*]*([^\t\n]+)/i),
        resultado_aprendizaje: j.general && j.general.resultado_aprendizaje,
        unidades: unidadesSyllabus.length ? unidadesSyllabus : [{ numero: j.unidad && j.unidad.numero, nombre: j.unidad && j.unidad.nombre }]
      },
      presentacion: {
        ...j.presentacion,
        requerida: numero === PRESENTACION_EN_TEMA,
        formato: 'Presentación interactiva de la asignatura (' + presEstructura.pantallas + ' pantallas)',
        estructura_red: presEstructura
      },
      recursos,
      evaluacion: { ...j.evaluacion, requisitos: requisitosEvaluacion(asignada, j.estructura_red) }
    },
    pairedItem: { item: idx }
  };
});

// Nodo Code: «Auditar gancho de micro-learning» · Modo: Run Once for All Items
// Va entre «Auditar borrador» y «¿Seguir corrigiendo?». Suma a los errores de la auditoría los del formato de micro-learning
// (gancho en la primera escena y su duración, trato de tú y frases habladas). Usa el mismo formato de error que «Auditar borrador»
// («Tema N: recurso K: … [campo: contenido]») para que «Preparar ajustes individuales» los convierta en tareas de corrección.
// Solo revisa los recursos cuya hoja los marca como video_micro; los demás pasan sin cambios.

const informe = $input.first().json;
const bases = $('Completar requisitos RED').all().map(x => x.json);
const temas = (informe.borradores || []).map(b => b.output || b);
const MAX_RONDAS = 3;       // el mismo tope que «Auditar borrador»
const MAX_PALABRAS_FRASE = 25;
const PALABRAS_POR_SEGUNDO = 2.5;   // ritmo de una narración hablada
const TOLERANCIA_GANCHO = 1.2;      // margen sobre las palabras que caben en los segundos de la hoja

const limpio = x => String(x ?? '').replace(/\s+/g, ' ').trim();
const palabras = t => (limpio(t).match(/\S+/g) || []).length;
const frases = t => limpio(t).split(/(?<=[.!?…])\s+/).filter(Boolean);
const RE_APERTURA = /^[¡¿"“«\s]*(?:hola|buenas|buenos|bienvenid\w*|hoy[\s,:]|en este (?:video|recurso|micro)|vamos a|veremos|aprender(?:ás|emos)|el objetivo|objetivo[:\s])/i;
const RE_DEFINICION = /\b(?:se define como|se denomina|consiste en|es el proceso de|es la capacidad de)\b/i;
const RE_USTED = /\busted(?:es)?\b/i;

// Segundos máximos del gancho según la hoja: «gancho de máximo 10 segundos» o «gancho (00:00–00:20)».
const segundosGancho = ficha => {
  const er = (ficha && ficha.estructura_red) || {};
  const texto = limpio(er.extension) + ' ' + limpio(er.estructura);
  const m = /gancho[^.;\n]{0,60}?m[aá]xim[oa]\s*(?:de\s*)?(\d+)\s*segundos/i.exec(texto) || /gancho\s*\(\s*00:00\s*[–-]\s*00:(\d{2})\s*\)/i.exec(texto);
  return m ? Number(m[1]) : null;
};

const errores = [...(informe.errores || [])];
const agregados = [];

bases.forEach((base, i) => {
  const n = base.tema && base.tema.numero;
  const borrador = temas[i] || {};
  (borrador.recursos || []).forEach(rec => {
    const ficha = (base.recursos || []).find(x => x.posicion === rec.posicion);
    const clave = ficha && ficha.reglas_formato && ficha.reglas_formato.clave;
    if (clave !== 'video_micro') return;
    const escenas = Array.isArray(rec.contenido) ? rec.contenido : [];
    if (!escenas.length) return;
    const prefijo = 'Tema ' + n + ': recurso ' + rec.posicion + ': ';
    const nuevos = [];   // { m: mensaje, campo }

    const primera = limpio(escenas[0] && escenas[0].texto);
    const inicio = frases(primera)[0] || '';
    if (RE_APERTURA.test(primera)) {
      nuevos.push({ campo: 'contenido', m: 'la escena 1 debe ser un gancho: abra con una situación concreta, un error frecuente o una contradicción, sin saludo, sin «hoy vamos a…» y sin presentar el objetivo.' });
    } else if (RE_DEFINICION.test(inicio)) {
      nuevos.push({ campo: 'contenido', m: 'la escena 1 abre con una definición; abra con un gancho (situación concreta o error frecuente con tensión sin resolver) y deje la definición para después.' });
    }

    const segundos = segundosGancho(ficha);
    if (segundos) {
      const topeHablado = Math.round(segundos * PALABRAS_POR_SEGUNDO);
      const topeAuditoria = Math.round(segundos * PALABRAS_POR_SEGUNDO * TOLERANCIA_GANCHO);
      const dichas = palabras(primera);
      if (dichas > topeAuditoria) {
        nuevos.push({ campo: 'contenido', m: 'el gancho (escena 1) tiene ' + dichas + ' palabras y la hoja pide máximo ' + segundos + ' segundos, unas ' + topeHablado + ' palabras habladas; acórtelo a ese tamaño sin perder la tensión.' });
      }
    }

    const conUsted = escenas.map((s, k) => [k + 1, s]).filter(([, s]) => RE_USTED.test(limpio(s && s.texto) + ' ' + limpio(s && s.texto_visible))).map(([k]) => k);
    if (conUsted.length) {
      nuevos.push({ campo: 'contenido', m: 'el micro-learning se habla de tú, no de usted (escena' + (conUsted.length > 1 ? 's ' : ' ') + conUsted.join(', ') + ').' });
    }

    const largas = [];
    escenas.forEach((s, k) => frases(s && s.texto).forEach(f => { if (palabras(f) > MAX_PALABRAS_FRASE) largas.push(k + 1); }));
    if (largas.length) {
      const unicas = [...new Set(largas)];
      nuevos.push({ campo: 'contenido', m: 'hay frases de la narración demasiado largas para un video hablado (escena' + (unicas.length > 1 ? 's ' : ' ') + unicas.join(', ') + '); divídalas en frases de máximo 15 palabras.' });
    }

    // Los complementos (por ejemplo la pregunta de comprensión) también se hablan de tú.
    (Array.isArray(rec.complementos) ? rec.complementos : []).forEach(c => {
      if (c && RE_USTED.test(limpio(c.texto))) {
        nuevos.push({ campo: 'complementos', m: 'el complemento «' + limpio(c.rotulo) + '» habla de usted; en micro-learning se habla de tú.' });
      }
    });

    nuevos.forEach(({ m, campo }) => { errores.push(prefijo + m + ' [campo: ' + campo + ']'); agregados.push(prefijo + m); });
  });
});

const ronda = Number(informe.ronda) || 0;
return [{
  json: {
    ...informe,
    errores,
    requiere_correccion: errores.length > 0,
    seguir_corrigiendo: errores.length > 0 && ronda < MAX_RONDAS,
    errores_gancho: agregados
  }
}];

// Nodo Code: «Reordenar bloques del guion» · Modo: Run Once for All Items
// Va después de «Rellenar copia del guion» y «Leer copia rellena». Google Docs no tiene «mover bloque»: para que los recursos
// queden en el orden de la unidad se reconstruye cada bloque (título + tabla) en su nueva posición y luego se borran los originales.
//   - Cada bloque se identifica por su título «Recurso NN · …» seguido de una tabla; su posición en la unidad sale del
//     «Código del recurso» (U#-T#-R#). El bloque sin código (presentación de la asignatura) va primero.
//   - Todos los bloques nuevos se insertan, del último al primero, en el mismo índice (justo después del último bloque original):
//     así ningún índice depende de cuánto mide lo que va después. Dentro de una tabla, el párrafo de cada celda se calcula
//     sobre la tabla vacía y las celdas se escriben de la más alta a la más baja.
//   - Al final se borran los bloques originales, de una sola vez.
// Si algo no cuadra (contenido entre bloques, elementos no previstos, orden ya correcto, error al leer el documento) no se
// cambia nada: se devuelve una petición inocua y el documento queda como está. «Aplicar orden de bloques» no detiene el flujo si falla.

const REORDENAR_BLOQUES = true;    // false: el documento queda en el orden de la plantilla
const QUITAR_NUMERACION = true;   // true: «Recurso 05 · Videos…» pasa a «Videos…» en todos los títulos de recurso
const UNIR_BANDAS = true;          // false: las bandas de sección no se combinan en una sola celda

const NO_OP = { replaceAllText: { containsText: { text: '<<SIN_REORDENAR>>', matchCase: true }, replaceText: '' } };
// Los títulos de la plantilla y de los recursos agregados empiezan por «Recurso NN · »; se quita ese prefijo (los números de la plantilla no son los de la unidad).
const QUITAR_NUMEROS = QUITAR_NUMERACION ? Array.from({ length: 40 }, (_, n) => ({ replaceAllText: { containsText: { text: 'Recurso ' + String(n).padStart(2, '0') + ' · ', matchCase: true }, replaceText: '' } })) : [];
const SIN_CAMBIOS = [NO_OP, ...QUITAR_NUMEROS];
const TS_CAMPOS = 'bold,italic,underline,strikethrough,foregroundColor,backgroundColor,fontSize,weightedFontFamily';
const PS_CAMPOS = 'namedStyleType,alignment,lineSpacing,spacingMode,spaceAbove,spaceBelow,indentFirstLine,indentStart,indentEnd,keepLinesTogether,keepWithNext,avoidWidowAndOrphan,pageBreakBefore';
// Dentro de una tabla Docs rechaza pageBreakBefore y keepWithNext.
const PS_CELDA = PS_CAMPOS.split(',').filter(k => k !== 'pageBreakBefore' && k !== 'keepWithNext').join(',');
const CS_CAMPOS = 'backgroundColor,paddingLeft,paddingRight,paddingTop,paddingBottom';
// Docs devuelve las medidas en cero como {unit:'PT'} (sin magnitud); al reenviarlas se escribe el cero de forma explícita.
const conCero = v => (v && typeof v === 'object' && v.unit && v.magnitude === undefined ? { magnitude: 0, unit: v.unit } : v);
// Docs lee la fuente como {fontFamily, weight: 400}; si se reenvía el peso 400 anula la negrilla heredada del estilo (los títulos H1 son negrilla por estilo). Se envía solo la familia.
const sinPeso = v => (v && typeof v === 'object' && v.fontFamily ? { fontFamily: v.fontFamily } : v);
const soloCampos = (objeto, lista) => { const salida = {}; lista.split(',').forEach(k => { if (objeto && objeto[k] !== undefined) salida[k] = k === 'weightedFontFamily' ? sinPeso(objeto[k]) : conCero(objeto[k]); }); return salida; };

const textoPar = p => (p.elements || []).map(e => (e.textRun ? e.textRun.content : '')).join('');
const textoCelda = celda => (celda.content || []).map(e => (e.paragraph ? textoPar(e.paragraph) : '')).join('');

// ---------- análisis del documento ----------
function bloquesDe(contenido) {
  const bloques = [];
  for (let k = 0; k < contenido.length - 1; k++) {
    const el = contenido[k], sig = contenido[k + 1];
    if (el.paragraph && el.paragraph.paragraphStyle && el.paragraph.paragraphStyle.namedStyleType === 'HEADING_1' && sig.table && /^C[oó]digo del recurso/i.test(sig.table.tableRows[0] && sig.table.tableRows[0].tableCells[0] ? textoCelda(sig.table.tableRows[0].tableCells[0]).trim() : '')) {
      const codigo = sig.table.tableRows[0] && sig.table.tableRows[0].tableCells[1] ? textoCelda(sig.table.tableRows[0].tableCells[1]) : '';
      const m = /-R(\d+)\s*$/.exec(codigo.trim());
      const ini = k > 0 && contenido[k - 1].paragraph && textoPar(contenido[k - 1].paragraph).trim() === '' ? contenido[k - 1] : null;
      bloques.push({ k, ini, h: el, t: sig, posicion: m ? Number(m[1]) : 0, codigo: codigo.trim(), titulo: textoPar(el.paragraph).trim() });
    }
  }
  return bloques;
}

function planear(contenido) {
  const bloques = bloquesDe(contenido);
  if (bloques.length < 2) return { motivo: 'menos de dos bloques' };
  // solo párrafos vacíos entre un bloque y el siguiente
  for (let m = 0; m < bloques.length - 1; m++) {
    for (let k = bloques[m].k + 2; k < bloques[m + 1].k; k++) {
      const el = contenido[k];
      if (!el.paragraph || textoPar(el.paragraph).trim() !== '') return { motivo: 'hay contenido entre bloques (elemento ' + k + ')' };
    }
  }
  // cada bloque empieza con su párrafo en blanco inicial (ahí vive el salto de página)
  for (const b of bloques) if (!b.ini) return { motivo: 'un bloque no tiene párrafo inicial' };
  // solo elementos previstos dentro de los bloques
  for (const b of bloques) {
    for (const e of b.h.paragraph.elements) if (!e.textRun) return { motivo: 'título con elementos no previstos' };
    for (const row of b.t.table.tableRows) for (const cell of row.tableCells) for (const e of cell.content) {
      if (!e.paragraph) return { motivo: 'celda con elementos no previstos' };
      for (const r of e.paragraph.elements) if (!r.textRun) return { motivo: 'celda con elementos no previstos' };
    }
  }
  const orden = bloques.map((b, i) => ({ b, i })).sort((x, y) => x.b.posicion - y.b.posicion || x.i - y.i).map(x => x.b);
  if (orden.every((b, i) => b === bloques[i])) return { motivo: 'el orden ya es el de la unidad', antes: bloques.map(b => b.posicion) };
  return { bloques, orden };
}

// ---------- clonado de un bloque ----------
function clonarBloque(b, E, separador, huecos) {
  const reqs = [];
  const tabla = b.t.table;
  const filas = tabla.tableRows.length;
  const columnas = tabla.tableRows[0].tableCells.length;
  const inicioTabla = E + 1;
  const parrafo = (r, c) => E + 4 + r * (1 + 2 * columnas) + 2 * c;

  // 1) párrafos en blanco después de la tabla (los mismos que deja la plantilla)
  const psSep = separador && separador.paragraph ? separador.paragraph.paragraphStyle : { namedStyleType: 'NORMAL_TEXT' };
  if (huecos > 0) {
    reqs.push({ insertText: { location: { index: E }, text: '\n'.repeat(huecos) } });
    reqs.push({ updateParagraphStyle: { range: { startIndex: E, endIndex: E + huecos }, paragraphStyle: soloCampos(psSep, PS_CAMPOS), fields: PS_CAMPOS } });
    const run = separador && separador.paragraph && separador.paragraph.elements[0] && separador.paragraph.elements[0].textRun;
    reqs.push({ updateTextStyle: { range: { startIndex: E, endIndex: E + huecos }, textStyle: soloCampos(run && run.textStyle, TS_CAMPOS), fields: TS_CAMPOS } });
  }

  // 2) tabla vacía, anchos, filas y estilos de celda
  reqs.push({ insertTable: { location: { index: E }, rows: filas, columns: columnas } });
  const props = (tabla.tableStyle && tabla.tableStyle.tableColumnProperties) || [];
  props.forEach((p, c) => {
    reqs.push({ updateTableColumnProperties: { tableStartLocation: { index: inicioTabla }, columnIndices: [c], tableColumnProperties: { widthType: p.widthType, ...(p.width ? { width: p.width } : {}) }, fields: p.width ? 'widthType,width' : 'widthType' } });
  });
  tabla.tableRows.forEach((row, r) => {
    const prevenir = row.tableRowStyle && row.tableRowStyle.preventOverflow;
    if (prevenir !== undefined) reqs.push({ updateTableRowStyle: { tableStartLocation: { index: inicioTabla }, rowIndices: [r], tableRowStyle: { preventOverflow: prevenir }, fields: 'preventOverflow' } });
    row.tableCells.forEach((cell, c) => {
      reqs.push({ updateTableCellStyle: {
        tableRange: { tableCellLocation: { tableStartLocation: { index: inicioTabla }, rowIndex: r, columnIndex: c }, rowSpan: 1, columnSpan: 1 },
        tableCellStyle: soloCampos(cell.tableCellStyle, CS_CAMPOS), fields: CS_CAMPOS
      } });
    });
  });

  // 3) texto de cada celda, de la más alta a la más baja
  const celdas = [];
  tabla.tableRows.forEach((row, r) => row.tableCells.forEach((cell, c) => celdas.push({ r, c, cell })));
  celdas.sort((x, y) => parrafo(y.r, y.c) - parrafo(x.r, x.c));
  celdas.forEach(({ r, c, cell }) => {
    const base = parrafo(r, c);
    const parrafos = cell.content.filter(e => e.paragraph).map(e => e.paragraph);
    const textos = parrafos.map(textoPar);
    const completo = textos.join('');
    const aInsertar = completo.slice(0, -1);   // el salto final lo aporta el párrafo vacío de la celda
    if (aInsertar) reqs.push({ insertText: { location: { index: base }, text: aInsertar } });
    let inicio = base;
    parrafos.forEach((p, j) => {
      const largo = textos[j].length;
      let corrido = 0;
      // primero el estilo de párrafo y después el de texto: al aplicar namedStyleType Docs borra el formato directo del texto
      reqs.push({ updateParagraphStyle: { range: { startIndex: inicio, endIndex: inicio + largo }, paragraphStyle: soloCampos(p.paragraphStyle, PS_CELDA), fields: PS_CELDA } });
      p.elements.forEach(e => {
        const s = e.textRun.content;
        reqs.push({ updateTextStyle: { range: { startIndex: inicio + corrido, endIndex: inicio + corrido + s.length }, textStyle: soloCampos(e.textRun.textStyle, TS_CAMPOS), fields: TS_CAMPOS } });
        corrido += s.length;
      });
      inicio += largo;
    });
  });

  // 4) celdas combinadas (bandas de sección)
  if (UNIR_BANDAS) {
    tabla.tableRows.forEach((row, r) => row.tableCells.forEach((cell, c) => {
      const cs = cell.tableCellStyle || {};
      if ((cs.columnSpan || 1) > 1 || (cs.rowSpan || 1) > 1) {
        reqs.push({ mergeTableCells: { tableRange: { tableCellLocation: { tableStartLocation: { index: inicioTabla }, rowIndex: r, columnIndex: c }, rowSpan: cs.rowSpan || 1, columnSpan: cs.columnSpan || 1 } } });
      }
    }));
  }

  // 5) párrafo inicial (con el salto de página) y título: van en el párrafo que Docs deja justo antes de la tabla
  const titulo = textoPar(b.h.paragraph);
  const textoTitulo = titulo.slice(0, -1);
  reqs.push({ insertText: { location: { index: E }, text: '\n' + textoTitulo } });
  let corrido = 0;
  reqs.push({ updateParagraphStyle: { range: { startIndex: E + 1, endIndex: E + 1 + titulo.length }, paragraphStyle: soloCampos(b.h.paragraph.paragraphStyle, PS_CAMPOS), fields: PS_CAMPOS } });
  b.h.paragraph.elements.forEach(e => {
    const s = e.textRun.content;
    reqs.push({ updateTextStyle: { range: { startIndex: E + 1 + corrido, endIndex: E + 1 + corrido + s.length }, textStyle: soloCampos({ ...e.textRun.textStyle, bold: undefined }, TS_CAMPOS), fields: TS_CAMPOS } });   // la negrilla del título la da el estilo H1; reenviar bold:true la dejaba en normal
    corrido += s.length;
  });
  const psIni = { ...((b.ini.paragraph && b.ini.paragraph.paragraphStyle) || {}), pageBreakBefore: true };
  reqs.push({ updateParagraphStyle: { range: { startIndex: E, endIndex: E + 1 }, paragraphStyle: soloCampos(psIni, PS_CAMPOS), fields: PS_CAMPOS } });
  const runIni = b.ini.paragraph.elements[0] && b.ini.paragraph.elements[0].textRun;
  reqs.push({ updateTextStyle: { range: { startIndex: E, endIndex: E + 1 }, textStyle: soloCampos(runIni && runIni.textStyle, TS_CAMPOS), fields: TS_CAMPOS } });
  return reqs;
}

// ---------- salida por documento ----------
const documentos = $input.all();
const bases = $('Preparar relleno del guion').all();
return documentos.map((item, i) => {
  const documento = (bases[i] && bases[i].json && bases[i].json.documento) || {};
  const sin = (estado, motivo, extra) => ({ json: { documento, requests: SIN_CAMBIOS, orden: { estado, motivo: motivo || null, ...(extra || {}) } } });
  if (!REORDENAR_BLOQUES) return sin('apagado');
  const doc = item.json || {};
  if (doc.error || !doc.body || !Array.isArray(doc.body.content)) return sin('omitido', 'no se pudo leer el documento');
  try {
    const contenido = doc.body.content;
    const plan = planear(contenido);
    if (!plan.orden) return sin('sin cambios', plan.motivo, plan.antes ? { posiciones: plan.antes } : undefined);
    const ultimo = plan.bloques[plan.bloques.length - 1];
    const E = ultimo.t.endIndex;
    const S = plan.bloques[0].ini.startIndex;
    const requests = [];
    // el párrafo de separación copia el estilo del primer espacio en blanco que sigue a un bloque (nunca el de un título)
    const primero = plan.bloques[0];
    const separador = contenido[contenido.indexOf(primero.t) + 1];
    const huecos = Math.max(0, plan.bloques[1].k - (primero.k + 2) - 1);   // párrafos en blanco entre la tabla y el párrafo inicial del bloque siguiente
    [...plan.orden].reverse().forEach((b, n) => {
      // el último bloque conserva los párrafos en blanco que ya había antes del anexo; los demás copian el hueco de la plantilla
      clonarBloque(b, E, separador, n === 0 ? 0 : huecos).forEach(r => requests.push(r));
    });
    requests.push({ deleteContentRange: { range: { startIndex: S, endIndex: E } } });
    QUITAR_NUMEROS.forEach(r => requests.push(r));
    return { json: { documento, requests, orden: { estado: 'reordenado', antes: plan.bloques.map(b => b.posicion), despues: plan.orden.map(b => b.posicion) } } };
  } catch (e) {
    return sin('omitido', 'error al planear: ' + String(e && e.message || e).slice(0, 160));
  }
});

// Nodo Code: «Cerrar reordenamiento» · Modo: Run Once for All Items
// Deja un ítem por documento y SIN clave «error», para que «preparar-respuesta-con-enlaces2-guiones» no se detenga
// aunque el reordenamiento haya fallado (en ese caso el documento queda con los bloques en el orden de la plantilla).
const ordenes = $('Reordenar bloques del guion').all();
return $input.all().map((it, i) => {
  const o = ordenes[i] && ordenes[i].json;
  const fallo = it.json && it.json.error ? String(it.json.error.message || JSON.stringify(it.json.error)).slice(0, 300) : null;
  return { json: { documento: (o && o.documento) || {}, orden_bloques: (o && o.orden) || null, aviso_orden: fallo } };
});
